export const WARROOM_HTML = "<!DOCTYPE html>\n<html lang=\"cs\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>WARROOM: FRONTLINES</title>\n    <style>\n        @import url('https://fonts.googleapis.com/css2?family=Share+Tech+Mono&display=swap');\n\n        :root { \n            --bg: #020617; --panel: rgba(15, 23, 42, 0.85); --border: #1e293b;\n            --accent: #10b981; --warning: #f59e0b; --danger: #ef4444;\n            --tech: #3b82f6; --text-main: #94a3b8; --purple: #a855f7;\n            --gold: #fbbf24; --cyan: #06b6d4; --toxic: #84cc16;\n        }\n\n        * { box-sizing: border-box; }\n        \n        body { \n            font-family: 'Share Tech Mono', monospace; background-color: var(--bg); color: var(--text-main); \n            display: flex; justify-content: center; align-items: center; min-height: 100vh; margin: 0; user-select: none;\n            background-image: radial-gradient(circle at center, #1a1f35 0%, #020617 100%); overflow: hidden;\n            box-shadow: inset 0 0 150px rgba(0,0,0,1);\n        }\n\n        body::after {\n            content: \"\"; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;\n            background: repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.15), rgba(0, 0, 0, 0.15) 1px, transparent 1px, transparent 2px);\n            pointer-events: none; z-index: 1000;\n        }\n\n        h1, h2, h3, h4, button, .stat-value, .badge { text-shadow: 0 0 4px currentColor; }\n\n        .glass-panel {\n            background: var(--panel); border: 1px solid var(--border); border-radius: 12px;\n            backdrop-filter: blur(10px); box-shadow: 0 10px 40px rgba(0,0,0,0.8), inset 0 0 40px rgba(0,0,0,0.6);\n        }\n\n        .wizard-screen { display: none; text-align: center; max-width: 1150px; width: 95%; padding: 30px; z-index: 10; position: relative; max-height: 95vh; overflow-y: auto;}\n        .wizard-screen.active { display: block; animation: fadeInUI 0.4s ease-out; }\n        \n        .scenarios-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 15px; margin-top: 20px;}\n        @media (max-width: 1000px) { .scenarios-grid { grid-template-columns: repeat(2, 1fr); } }\n        @media (max-width: 550px) { .scenarios-grid { grid-template-columns: 1fr; } }\n        \n        .card { background: rgba(0,0,0,0.5); border: 1px solid var(--border); padding: 15px; border-radius: 8px; cursor: pointer; transition: all 0.2s; text-align: left; position: relative; overflow: hidden;}\n        .card:not(.locked-card):hover { border-color: var(--tech); background: rgba(59, 130, 246, 0.1); transform: translateY(-3px); box-shadow: 0 5px 15px rgba(59, 130, 246, 0.2); }\n        .card h4 { margin: 15px 0 8px 0; color: #fff; font-size: 0.95rem; letter-spacing: 1px;}\n        .card .scenario-tag { position: absolute; top: 10px; right: 10px; font-size: 0.65rem; background: rgba(0,0,0,0.8); border: 1px solid var(--border); padding: 3px 8px; border-radius: 4px; color: #fff; font-weight: bold; z-index: 2;}\n        .scenario-year { font-size: 0.7rem; font-weight: normal; color: #6b7280; }\n        .card small { font-size: 0.75rem; display: block; padding-right: 5px; color: #8a99ad; }\n\n        .locked-card { opacity: 0.45; cursor: not-allowed; border-color: #1a222d !important; background: rgba(5,7,10,0.8) !important; }\n        .locked-card h4 { color: #556275 !important; text-shadow: none !important; }\n\n        #game-screen { display: none; width: 95%; max-width: 850px; padding: 25px; z-index: 10; position: relative; max-height: 95vh; overflow-y: auto;}\n        \n        .shake { animation: shakeAnim 0.3s ease-in-out; }\n        .crisis { animation: crisisPulse 2s infinite alternate; border-color: var(--danger) !important; }\n        @keyframes shakeAnim { 0%, 100% { transform: translate(0, 0); } 20%, 60% { transform: translate(-5px, 3px); } 40%, 80% { transform: translate(5px, -3px); } }\n        @keyframes crisisPulse { 0% { box-shadow: 0 0 15px rgba(239, 68, 68, 0.1); } 100% { box-shadow: 0 0 40px rgba(239, 68, 68, 0.4); } }\n        @keyframes fadeInUI { from { opacity: 0; transform: scale(0.98); } to { opacity: 1; transform: scale(1); } }\n\n        .header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; border-bottom: 1px dashed var(--border); padding-bottom: 15px; }\n        .header h2 { margin: 0; color: #fff; letter-spacing: 3px; font-size: 1.4rem; text-shadow: 0 0 10px rgba(255,255,255,0.5); }\n        .badge { background: rgba(0,0,0,0.6); border: 1px solid var(--border); padding: 5px 10px; border-radius: 6px; font-weight: bold; font-size: 0.85rem; margin-left: 6px; box-shadow: inset 0 0 5px rgba(0,0,0,0.5);}\n\n        .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 20px; text-align: center; }\n        .stat-box { background: rgba(0,0,0,0.5); padding: 10px; border-radius: 6px; border: 1px solid var(--border); font-size: 0.85rem; }\n        .stat-value { display: block; font-size: 1.4rem; font-weight: bold; margin-top: 6px; }\n\n        #scenario-module { border: 1px solid var(--border); background: rgba(0,0,0,0.4); padding: 12px; border-radius: 6px; margin-bottom: 20px; text-align: center; }\n        #scenario-status { font-weight: bold; font-size: 1.15rem; color: #fff; letter-spacing: 1px;}\n        #scenario-desc { font-size: 0.85rem; color: var(--text-main); margin-top: 5px; }\n\n        .gauge-wrap { height: 32px; background: #000; border: 2px solid var(--border); border-radius: 8px; position: relative; overflow: hidden; margin-bottom: 20px; box-shadow: inset 0 0 15px rgba(0,0,0,1); }\n        #gauge { height: 100%; background: var(--accent); width: 50%; transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1); }\n        .gauge-text { position: absolute; width: 100%; text-align: center; line-height: 32px; color: #fff; font-weight: bold; z-index: 5; text-shadow: 1px 1px 3px #000; font-size: 1rem; letter-spacing: 1px;}\n        .vietnam-hidden #gauge { background: #111 !important; }\n        .vietnam-hidden .gauge-text { color: #444; }\n\n        #radar-wrap { display: none; margin: 20px 0; }\n        #radar { height: 70px; background: #020305; position: relative; border: 2px solid var(--border); border-radius: 6px; cursor: crosshair; overflow: hidden; box-shadow: inset 0 0 20px rgba(16,185,129,0.05); }\n        .target-zone { position: absolute; top: 0; height: 100%; background: rgba(16, 185, 129, 0.2); border-left: 2px dashed var(--accent); border-right: 2px dashed var(--accent); }\n        #pointer { position: absolute; top: 0; left: 50%; width: 3px; height: 100%; background: #fff; box-shadow: 0 0 10px #fff; }\n\n        .section-title { font-size: 0.85rem; text-transform: uppercase; color: #fff; margin: 20px 0 10px 0; letter-spacing: 2px; border-bottom: 1px solid var(--border); padding-bottom: 5px; }\n        .grid-buttons { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 12px; }\n        .grid-3 { grid-template-columns: repeat(3, 1fr); }\n        \n        .grid-upgrades { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 12px; }\n        @media (max-width: 768px) { .grid-upgrades { grid-template-columns: repeat(2, 1fr); } }\n        @media (max-width: 480px) { .grid-upgrades { grid-template-columns: 1fr; } }\n        \n        button { \n            font-family: 'Share Tech Mono', monospace; padding: 12px; border: 1px solid var(--border); \n            border-radius: 6px; cursor: pointer; transition: all 0.1s ease-in-out; text-transform: uppercase; \n            font-weight: bold; font-size: 0.9rem; position: relative; overflow: hidden;\n            box-shadow: 0 4px 0 rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.05);\n        }\n        button:active:not(:disabled) { transform: translateY(4px); box-shadow: 0 0px 0 rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.05); }\n        button::before {\n            content: \"\"; position: absolute; top: 0; left: -100%; width: 50%; height: 100%;\n            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent); transform: skewX(-20deg); transition: 0s;\n        }\n        button:hover:not(:disabled)::before { animation: buttonShine 0.6s forwards; }\n        @keyframes buttonShine { 100% { left: 200%; } }\n\n        button:disabled { \n            opacity: 0.4 !important; cursor: not-allowed; filter: grayscale(100%); \n            background: rgba(0,0,0,0.5) !important; border-color: #222 !important; \n            color: #666 !important; transform: translateY(0) !important; \n            box-shadow: 0 4px 0 #111 !important; text-shadow: none;\n        }\n\n        .btn-main { background: linear-gradient(180deg, rgba(16, 185, 129, 0.15), rgba(16, 185, 129, 0.05)); color: var(--accent); border-color: var(--accent); box-shadow: 0 4px 0 rgba(16,185,129,0.3); }\n        .btn-warn { background: linear-gradient(180deg, rgba(245, 158, 11, 0.15), rgba(245, 158, 11, 0.05)); color: var(--warning); border-color: var(--warning); box-shadow: 0 4px 0 rgba(245,158,11,0.3); }\n        .btn-tech { background: linear-gradient(180deg, rgba(59, 130, 246, 0.15), rgba(59, 130, 246, 0.05)); color: var(--tech); border-color: var(--tech); box-shadow: 0 4px 0 rgba(59,130,246,0.3); }\n        .btn-spec { background: linear-gradient(180deg, rgba(168, 85, 247, 0.15), rgba(168, 85, 247, 0.05)); color: var(--purple); border-color: var(--purple); box-shadow: 0 4px 0 rgba(168,85,247,0.3); }\n        .btn-gold { background: linear-gradient(180deg, rgba(251, 191, 36, 0.15), rgba(251, 191, 36, 0.05)); color: var(--gold); border-color: var(--gold); box-shadow: 0 4px 0 rgba(251,191,36,0.3); }\n\n        .terminal-log { background: #000; border: 1px solid var(--border); padding: 12px; height: 140px; overflow-y: auto; font-size: 0.85rem; display: flex; flex-direction: column; gap: 6px; margin-top: 20px; border-radius: 6px; box-shadow: inset 0 0 10px rgba(0,0,0,1);}\n        .log-entry { animation: fadeIn 0.2s forwards; border-left: 2px solid transparent; padding-left: 5px;}\n        .log-entry.t-green { border-color: var(--accent); } .log-entry.t-red { border-color: var(--danger); }\n        @keyframes fadeIn { from { opacity: 0; transform: translateX(-5px); } to { opacity: 1; transform: translateX(0); } }\n\n        .t-green { color: var(--accent); } .t-red { color: var(--danger); } .t-orange { color: var(--warning); } \n        .t-blue { color: var(--tech); } .t-white { color: #fff; } .t-purple { color: var(--purple); } \n        .t-gold { color: var(--gold); } .t-cyan { color: var(--cyan); } .t-toxic { color: var(--toxic); } .t-gray { color: #556275; }\n\n        #overlay-sector {\n            display: none; position: absolute; top: 0; left: 0; width: 100%; height: 100%;\n            background: rgba(0,0,0,0.9); z-index: 50; flex-direction: column; justify-content: center; align-items: center;\n            border-radius: 12px; backdrop-filter: blur(5px); animation: fadeInUI 0.4s ease-out;\n        }\n        #overlay-sector h1 { color: var(--accent); font-size: 2.5rem; letter-spacing: 5px; margin-bottom: 10px; text-align: center;}\n        #overlay-sector p { color: #fff; margin-bottom: 30px; font-size: 1.1rem;}\n        \n        .upg-info { font-size: 0.7rem; color: #8a99ad; display: block; margin-top: 3px; font-weight: normal;}\n\n        /* Toasts popups style */\n        .toast-notification {\n            position: fixed; top: 20px; right: -350px; width: 300px; \n            background: rgba(16, 24, 35, 0.95); border: 2px solid var(--accent);\n            color: #fff; padding: 15px; border-radius: 8px; font-weight: bold;\n            z-index: 2000; box-shadow: 0 5px 25px rgba(0,0,0,0.7);\n            font-family: 'Share Tech Mono', monospace;\n            transition: right 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n        }\n        .toast-notification.active { right: 20px; }\n        .toast-title { color: var(--accent); font-size: 0.8rem; letter-spacing: 1px; margin-bottom: 5px; text-transform: uppercase; }\n        .toast-body { font-size: 0.95rem; }\n\n        /* ===== MODERNIZACE: pozad\u00ed, HUD prvky, feedback efekty ===== */\n\n        body::before {\n            content: \"\"; position: fixed; top: 50%; left: 50%; width: 2600px; height: 2600px;\n            margin: -1300px 0 0 -1300px; pointer-events: none; z-index: 0;\n            background: conic-gradient(from 0deg, rgba(16,185,129,0.09), transparent 18%, transparent 100%);\n            animation: radarSweep 7s linear infinite;\n        }\n        @keyframes radarSweep { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }\n\n        #sound-toggle {\n            position: fixed; top: 16px; left: 16px; z-index: 1500; width: 46px; height: 46px;\n            border-radius: 50%; border: 1px solid var(--border); background: rgba(15,23,42,0.85);\n            color: var(--text-main); font-size: 1.2rem; display: flex; align-items: center; justify-content: center;\n            cursor: pointer; backdrop-filter: blur(6px); box-shadow: 0 4px 15px rgba(0,0,0,0.6);\n            transition: all 0.2s;\n        }\n        #sound-toggle:hover { border-color: var(--accent); color: var(--accent); transform: scale(1.08); }\n        #sound-toggle.muted { color: #556275; }\n\n        .float-text {\n            position: fixed; font-weight: bold; font-size: 1.1rem; pointer-events: none; z-index: 900;\n            text-shadow: 0 0 6px currentColor, 1px 1px 3px #000; animation: floatUp 1.2s ease-out forwards;\n            white-space: nowrap;\n        }\n        @keyframes floatUp {\n            0%   { opacity: 0; transform: translateY(0) scale(0.85); }\n            15%  { opacity: 1; transform: translateY(-8px) scale(1.05); }\n            100% { opacity: 0; transform: translateY(-75px) scale(1); }\n        }\n\n        .particle {\n            position: fixed; width: 5px; height: 5px; border-radius: 50%; pointer-events: none; z-index: 899;\n            transition: transform 0.6s cubic-bezier(0.15, 0.7, 0.4, 1), opacity 0.6s ease-out;\n        }\n\n        .flash-good { animation: flashGood 0.5s ease-out; }\n        .flash-bad { animation: flashBad 0.5s ease-out; }\n        @keyframes flashGood { 0% { box-shadow: 0 0 0 3px rgba(16,185,129,0.9), inset 0 0 15px rgba(16,185,129,0.6); } 100% { box-shadow: none; } }\n        @keyframes flashBad  { 0% { box-shadow: 0 0 0 3px rgba(239,68,68,0.9), inset 0 0 15px rgba(239,68,68,0.6); } 100% { box-shadow: none; } }\n\n        #vignette-flash {\n            position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; pointer-events: none; z-index: 800;\n            opacity: 0; background: radial-gradient(circle, transparent 40%, rgba(239,68,68,0.35) 100%);\n        }\n        #vignette-flash.hit { animation: vignetteHit 0.6s ease-out; }\n        @keyframes vignetteHit { 0% { opacity: 1; } 100% { opacity: 0; } }\n\n        @media (max-width: 550px) {\n            #sound-toggle { width: 40px; height: 40px; font-size: 1rem; top: 10px; left: 10px; }\n        }\n\n        /* Skryt\u00e9 pole pro cheat k\u00f3d - vypad\u00e1 jako ne\u0161kodn\u00e9 \u010d\u00edslo verze */\n        #cheat-input {\n            position: fixed; bottom: 4px; left: 50%; transform: translateX(-50%);\n            width: 100px; height: 16px; font-size: 9px; text-align: center;\n            background: transparent; border: none; color: rgba(255,255,255,0.12);\n            z-index: 1400; outline: none; font-family: 'Share Tech Mono', monospace;\n            letter-spacing: 1px; caret-color: transparent;\n        }\n        #cheat-input:focus { caret-color: rgba(255,255,255,0.3); }\n\n        #cheat-menu {\n            display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%;\n            background: rgba(0,0,0,0.88); z-index: 3000; justify-content: center; align-items: center;\n            backdrop-filter: blur(6px); animation: fadeInUI 0.3s ease-out;\n        }\n        .cheat-panel {\n            background: rgba(20,20,25,0.98); border: 2px solid #fbbf24; border-radius: 12px;\n            padding: 30px; width: 90%; max-width: 420px; text-align: center;\n            box-shadow: 0 0 40px rgba(251,191,36,0.3);\n        }\n        .cheat-panel h2 { color: #fbbf24; letter-spacing: 2px; margin-bottom: 8px; }\n        .cheat-sub { color: #9ca3af; font-size: 0.85rem; margin-bottom: 20px; }\n        .cheat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 20px; }\n        .cheat-grid button {\n            padding: 14px 8px; background: rgba(251,191,36,0.1); border: 1px solid #fbbf24;\n            color: #fbbf24; border-radius: 8px; cursor: pointer; font-family: inherit; font-weight: bold;\n            font-size: 0.85rem; transition: all 0.15s;\n        }\n        .cheat-grid button:hover { background: rgba(251,191,36,0.25); transform: scale(1.03); }\n        .cheat-close {\n            width: 100%; padding: 12px; background: rgba(239,68,68,0.15); border: 1px solid var(--danger);\n            color: var(--danger); border-radius: 8px; cursor: pointer; font-family: inherit; font-weight: bold;\n        }\n        .cheat-close:hover { background: rgba(239,68,68,0.3); }\n\n        /* ===== TUTORI\u00c1L ===== */\n        #tutorial-help-btn {\n            position: fixed; top: 16px; left: 70px; z-index: 1500; width: 46px; height: 46px;\n            border-radius: 50%; border: 1px solid var(--border); background: rgba(15,23,42,0.85);\n            color: var(--accent); font-size: 1.3rem; font-weight: bold; display: flex; align-items: center; justify-content: center;\n            cursor: pointer; backdrop-filter: blur(6px); box-shadow: 0 4px 15px rgba(0,0,0,0.6);\n        }\n        #tutorial-help-btn:hover { border-color: var(--accent); transform: scale(1.08); }\n        @media (max-width: 550px) { #tutorial-help-btn { width: 40px; height: 40px; font-size: 1.1rem; top: 10px; left: 58px; } }\n\n        #tutorial-intro {\n            display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%;\n            background: rgba(0,0,0,0.92); z-index: 2800; justify-content: center; align-items: center;\n            backdrop-filter: blur(6px); animation: fadeInUI 0.4s ease-out;\n        }\n        .tutorial-intro-panel {\n            background: rgba(15,20,28,0.98); border: 2px solid var(--accent); border-radius: 12px;\n            padding: 35px; width: 90%; max-width: 480px; text-align: center;\n            box-shadow: 0 0 40px rgba(16,185,129,0.25);\n        }\n        .tutorial-intro-panel h2 { color: var(--accent); letter-spacing: 1px; margin-bottom: 15px; font-size: 1.3rem; }\n        .tutorial-intro-panel p { color: #d1d5db; font-size: 0.9rem; line-height: 1.6; margin-bottom: 25px; }\n        .tutorial-intro-btns { display: flex; flex-direction: column; gap: 10px; }\n        .tutorial-intro-btns button { padding: 14px; font-size: 0.9rem; }\n\n        #tutorial-overlay { display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; z-index: 2600; pointer-events: none; }\n        #tutorial-spotlight {\n            position: fixed; border-radius: 10px; pointer-events: none; z-index: 2601;\n            box-shadow: 0 0 0 9999px rgba(0,0,0,0.78);\n            border: 2px solid var(--accent);\n            transition: top 0.35s ease, left 0.35s ease, width 0.35s ease, height 0.35s ease;\n        }\n        #tutorial-box {\n            position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%);\n            width: 90%; max-width: 480px; background: rgba(15,20,28,0.98); border: 2px solid var(--accent);\n            border-radius: 12px; padding: 20px; z-index: 2602; pointer-events: auto;\n            box-shadow: 0 0 30px rgba(16,185,129,0.25);\n        }\n        #tutorial-text { color: #fff; font-size: 0.9rem; line-height: 1.5; margin-bottom: 8px; }\n        #tutorial-hint { font-size: 0.8rem; margin-bottom: 12px; min-height: 1em; font-weight: bold; }\n        #tutorial-nav { display: flex; justify-content: space-between; align-items: center; gap: 10px; }\n        #tutorial-skip-btn { background: none; border: none; color: #6b7280; font-family: inherit; font-size: 0.8rem; cursor: pointer; text-decoration: underline; }\n        #tutorial-skip-btn:hover { color: #9ca3af; }\n        #tutorial-next-btn { padding: 10px 20px; background: var(--accent); color: #04120c; border: none; border-radius: 6px; font-weight: bold; cursor: pointer; font-family: inherit; }\n        #tutorial-next-btn:hover { filter: brightness(1.1); }\n        #tutorial-next-btn.hidden-nav { display: none; }\n    </style>\n</head>\n<body>\n<a href=\"/games\" id=\"btn-back-to-jomarid\" onclick=\"if (window.parent !== window) { window.parent.postMessage({ source: 'jomarid-game', type: 'close' }, '*'); return false; }\" style=\"position:fixed; top:calc(10px + env(safe-area-inset-top,0px)); left:10px; z-index:9999; color:#94a3b8; font-size:11px; letter-spacing:0.5px; text-decoration:none; background:rgba(2,6,23,0.75); padding:6px 10px; border-radius:8px; border:1px solid #1e293b; backdrop-filter: blur(4px); font-family: 'Share Tech Mono', monospace;\">\u2190 Jomarid Books</a>\n\n<div id=\"vignette-flash\"></div>\n<button id=\"sound-toggle\" onclick=\"toggleSound()\" title=\"Zapnout/vypnout zvuk\">\ud83d\udd0a</button>\n\n<input type=\"text\" id=\"cheat-input\" maxlength=\"20\" autocomplete=\"off\" spellcheck=\"false\"\n    value=\"v4.2\"\n    onfocus=\"if(this.value==='v4.2') this.value='';\"\n    onblur=\"if(this.value==='') this.value='v4.2';\"\n    oninput=\"checkCheatCode(this.value)\">\n\n<button id=\"tutorial-help-btn\" onclick=\"startTutorial()\" title=\"Spustit tutori\u00e1l\">?</button>\n\n<div id=\"tutorial-intro\">\n    <div class=\"tutorial-intro-panel\">\n        <h2>\ud83c\udf96\ufe0f V\u00cdTEJ VE WARROOM: FRONTLINES</h2>\n        <p>Jsi velitel na vzd\u00e1len\u00e9 front\u011b. Mus\u00ed\u0161 dotla\u010dit linii z po\u010d\u00e1te\u010dn\u00ed pozice a\u017e na maximum d\u0159\u00edv, ne\u017e t\u011b zni\u010d\u00ed tlak nep\u0159\u00edtele. Projdi si kr\u00e1tk\u00fd interaktivn\u00ed tutori\u00e1l a nau\u010d se z\u00e1klady velen\u00ed.</p>\n        <div class=\"tutorial-intro-btns\">\n            <button class=\"btn-main\" onclick=\"startTutorial()\">SPUSTIT INTERAKTIVN\u00cd TUTORI\u00c1L</button>\n            <button class=\"btn-warn\" onclick=\"skipTutorial()\">P\u0158ESKO\u010cIT, CHCI HR\u00c1T ROVNOU</button>\n        </div>\n    </div>\n</div>\n\n<div id=\"tutorial-overlay\">\n    <div id=\"tutorial-spotlight\"></div>\n    <div id=\"tutorial-box\">\n        <div id=\"tutorial-text\"></div>\n        <div id=\"tutorial-hint\" class=\"t-orange\"></div>\n        <div id=\"tutorial-nav\">\n            <button id=\"tutorial-skip-btn\" onclick=\"skipTutorial()\">P\u0159esko\u010dit tutori\u00e1l</button>\n            <button id=\"tutorial-next-btn\" onclick=\"tutorialNext()\">Dal\u0161\u00ed \u203a</button>\n        </div>\n    </div>\n</div>\n\n<div id=\"cheat-menu\">\n    <div class=\"cheat-panel\">\n        <h2>\ud83d\udee0\ufe0f VELITELSK\u00c1 KONZOLE</h2>\n        <p class=\"cheat-sub\">Neofici\u00e1ln\u00ed ladic\u00ed n\u00e1stroje. Pou\u017eit\u00ed je na tvou vlastn\u00ed zodpov\u011bdnost.</p>\n        <div class=\"cheat-grid\">\n            <button onclick=\"cheatAction('cp')\">+1000 VB</button>\n            <button onclick=\"cheatAction('supplies')\">+500 Z\u00e1sob</button>\n            <button onclick=\"cheatAction('front')\">+200 Fronta</button>\n            <button onclick=\"cheatAction('maxfront')\">Vyhr\u00e1t sektor</button>\n            <button onclick=\"cheatAction('unlockall')\">Odemknout v\u0161e</button>\n            <button onclick=\"cheatAction('god')\" id=\"cheat-god-btn\">Nesmrtelnost: VYPNUTO</button>\n        </div>\n        <button class=\"cheat-close\" onclick=\"closeCheatMenu()\">ZAV\u0158\u00cdT KONZOLI</button>\n    </div>\n</div>\n\n<div id=\"screen-scenario\" class=\"wizard-screen active glass-panel\">\n    <h1 class=\"t-white\" style=\"letter-spacing:5px; margin-top:0; font-size: 2.2rem; text-shadow: 0 0 8px var(--tech);\">WARROOM: FRONTLINES</h1>\n    <p style=\"color: #8a99ad; margin-bottom: 25px;\">Zvolte d\u011bji\u0161t\u011b konfliktu. Pro odem\u010den\u00ed dal\u0161\u00edho sc\u00e9n\u00e1\u0159e mus\u00edte v p\u0159edchoz\u00edm dos\u00e1hnout <b>Sektoru 10</b>.</p>\n    \n    <div class=\"scenarios-grid\" id=\"scenarios-container\">\n        <!-- Generov\u00e1no dynamicky pomoc\u00ed JS -->\n    </div>\n\n    <div style=\"margin-top: 35px; border-top: 1px dashed var(--border); padding-top: 20px;\">\n        <button class=\"btn-warn\" style=\"font-size: 0.8rem; padding: 8px 16px;\" onclick=\"resetSave()\">VYMAZAT V\u0160ECHNY POZICE (RESET)</button>\n    </div>\n</div>\n\n<div id=\"screen-doctrine\" class=\"wizard-screen glass-panel\">\n    <h2 class=\"t-white\" style=\"letter-spacing:3px; margin-top:0;\">ZVOLTE DOKTR\u00cdNU VELEN\u00cd</h2>\n    <p style=\"color: #8a99ad; margin-bottom: 25px;\">N\u011bkter\u00e9 specializace jsou zpo\u010d\u00e1tku zam\u010den\u00e9 a vy\u017eaduj\u00ed spln\u011bn\u00ed bojov\u00fdch \u00fakol\u016f.</p>\n    \n    <div class=\"scenarios-grid\" style=\"grid-template-columns: repeat(3, 1fr);\" id=\"doctrines-container\">\n        <!-- Generov\u00e1no dynamicky pomoc\u00ed JS -->\n    </div>\n</div>\n\n<div id=\"game-screen\" class=\"glass-panel\">\n    <div id=\"overlay-sector\">\n        <h1 id=\"os-title\">SEKTOR DOBYT</h1>\n        <p id=\"os-desc\">Vynikaj\u00edc\u00ed pr\u00e1ce, veliteli. P\u0159esouv\u00e1me linie!</p>\n        <button class=\"btn-main\" onclick=\"nextSector()\" style=\"font-size:1.2rem; padding: 15px 30px;\">POKRA\u010cOVAT DO DAL\u0160\u00cd OBLASTI</button>\n    </div>\n\n    <div class=\"header\">\n        <h2>FRONTLINES <span style=\"font-size: 0.8rem; color: #555;\">v4.0</span></h2>\n        <div>\n            <span class=\"badge t-purple\" id=\"lbl-scenario\">SC\u00c9N\u00c1\u0158</span>\n            <span class=\"badge t-blue\" id=\"lbl-doctrine\">DOKTR\u00cdNA</span>\n            <span class=\"badge t-white\">DEN <span id=\"val-day\">1</span></span>\n        </div>\n    </div>\n\n    <div class=\"stats-grid\">\n        <div class=\"stat-box\">Z\u00e1soby<span class=\"stat-value t-orange\" id=\"val-sup\">10</span></div>\n        <div class=\"stat-box\">Velit. Body<span class=\"stat-value t-blue\" id=\"val-cp\">0</span></div>\n        <div class=\"stat-box\">Denn\u00ed Tlak<span class=\"stat-value t-red\" id=\"val-push\">-5</span></div>\n        <div class=\"stat-box\">Krit. \u0160ance<span class=\"stat-value t-green\" id=\"val-crit\">15%</span></div>\n    </div>\n\n    <div id=\"scenario-module\">\n        <div id=\"scenario-status\">STATUS</div>\n        <div id=\"scenario-desc\">Popis</div>\n    </div>\n\n    <div class=\"gauge-wrap\" id=\"gauge-container\">\n        <div class=\"gauge-text\" id=\"gauge-text\">FRONTLINE: <span id=\"val-front\">250</span> / 500</div>\n        <div id=\"gauge\"></div>\n    </div>\n\n    <div id=\"radar-wrap\">\n        <div id=\"radar\">\n            <div class=\"target-zone\" id=\"t-zone\"></div>\n            <div id=\"pointer\"></div>\n        </div>\n    </div>\n\n    <div id=\"controls-wrap\">\n        <div class=\"grid-buttons\">\n            <button class=\"btn-main\" id=\"btn-atk\" onclick=\"startAttack()\">OFENZ\u00cdVA</button>\n            <button class=\"btn-warn\" id=\"btn-sup\" onclick=\"doLogistics()\">LOGISTIKA</button>\n        </div>\n        \n        <div class=\"section-title\">Velitelstv\u00ed & Speci\u00e1ln\u00ed operace</div>\n        <div class=\"grid-buttons grid-3\" id=\"command-grid\">\n            <button class=\"btn-tech\" id=\"btn-art\" onclick=\"useArtillery()\">Bar\u00e1\u017e</button>\n            <button class=\"btn-tech\" id=\"btn-air\" onclick=\"useAirdrop()\">Shoz</button>\n            <button class=\"btn-spec\" id=\"btn-scenario\" onclick=\"useScenarioSkill()\">SKILL</button>\n        </div>\n\n        <div class=\"section-title\">V\u00fdzkum a V\u00fdvoj (R&D) Glob\u00e1ln\u00ed Projekty</div>\n        <div class=\"grid-upgrades\" id=\"upgrades-grid\">\n            <button class=\"btn-tech\" id=\"upg-sup\" onclick=\"buyUpgrade('supply')\">Logistika <span id=\"cost-sup\">15</span><span class=\"upg-info\" id=\"info-sup\">V\u00fdnos +30%</span></button>\n            <button class=\"btn-tech\" id=\"upg-rad\" onclick=\"buyUpgrade('radar')\">Optika <span id=\"cost-rad\">25</span><span class=\"upg-info\" id=\"info-rad\">Z\u00f3na +25%</span></button>\n            <button class=\"btn-tech\" id=\"upg-dmg\" onclick=\"buyUpgrade('dmg')\">Zbran\u011b <span id=\"cost-dmg\">40</span><span class=\"upg-info\" id=\"info-dmg\">S\u00edla +20%</span></button>\n            <button class=\"btn-tech\" id=\"upg-cpg\" onclick=\"buyUpgrade('cpGain')\">Velen\u00ed <span id=\"cost-cpg\">20</span><span class=\"upg-info\" id=\"info-cpg\">P\u0159\u00edjem +20%</span></button>\n            <button class=\"btn-tech\" id=\"upg-arm\" onclick=\"buyUpgrade('armor')\">Panc\u00ed\u0159 <span id=\"cost-arm\">30</span><span class=\"upg-info\" id=\"info-arm\">Tlak -5%</span></button>\n            <button class=\"btn-tech\" id=\"upg-rec\" onclick=\"buyUpgrade('recon')\">Pr\u016fzkum <span id=\"cost-rec\">35</span><span class=\"upg-info\" id=\"info-rec\">Pasivn\u00ed VB</span></button>\n            \n            <!-- 3 Nov\u00e9 glob\u00e1ln\u00ed v\u00fdzkumy -->\n            <button class=\"btn-tech\" id=\"upg-crt\" onclick=\"buyUpgrade('critical')\">Kritika <span id=\"cost-crt\">30</span><span class=\"upg-info\" id=\"info-crt\">Crit \u0160ance +5%</span></button>\n            <button class=\"btn-tech\" id=\"upg-itg\" onclick=\"buyUpgrade('intel_gain')\">Rozv\u011bdka <span id=\"cost-itg\">25</span><span class=\"upg-info\" id=\"info-itg\">Tolerance z\u00e1sahu</span></button>\n            <button class=\"btn-tech\" id=\"upg-eng\" onclick=\"buyUpgrade('engineering')\">\u017denist\u00e9 <span id=\"cost-eng\">35</span><span class=\"upg-info\" id=\"info-eng\">Po\u010d\u00e1te\u010dn\u00ed HP +5%</span></button>\n        </div>\n        \n        <div class=\"section-title\">Exkluzivn\u00ed Taktick\u00e9 Moduly (Unik\u00e1tn\u00ed pro Sc\u00e9n\u00e1\u0159)</div>\n        <div class=\"grid-buttons grid-3\" id=\"exclusive-grid\" style=\"margin-bottom:0;\">\n            <button class=\"btn-gold\" id=\"btn-excl-1\" onclick=\"buyExclusiveTech(1)\">TECH 1</button>\n            <button class=\"btn-gold\" id=\"btn-excl-2\" onclick=\"buyExclusiveTech(2)\">TECH 2</button>\n            <button class=\"btn-gold\" id=\"btn-excl-3\" onclick=\"buyExclusiveTech(3)\">TECH 3</button>\n        </div>\n    </div>\n\n    <div class=\"terminal-log\" id=\"log\"></div>\n</div>\n\n<script>\n    const el = id => document.getElementById(id);\n\n    // =====================================================================\n    // ZVUKOV\u00dd ENGINE \u2014 v\u0161e generov\u00e1no procedur\u00e1ln\u011b p\u0159es Web Audio API,\n    // tak\u017ee hra nepot\u0159ebuje \u017e\u00e1dn\u00e9 extern\u00ed zvukov\u00e9 soubory.\n    // =====================================================================\n    const Sound = (() => {\n        let ctx = null, master = null, ambientStarted = false;\n        let muted = false;\n        try { muted = localStorage.getItem('warroom_muted') === '1'; } catch (e) { muted = false; }\n\n        function ensureCtx() {\n            if (!ctx) {\n                const AC = window.AudioContext || window.webkitAudioContext;\n                if (!AC) return null;\n                ctx = new AC();\n                master = ctx.createGain();\n                master.gain.value = muted ? 0 : 0.55;\n                master.connect(ctx.destination);\n            }\n            if (ctx.state === 'suspended') ctx.resume().catch(() => {});\n            return ctx;\n        }\n\n        function tone(freq, duration, type = 'sine', gain = 0.3, glideTo = null, delay = 0) {\n            const c = ensureCtx();\n            if (!c) return;\n            const t0 = c.currentTime + delay;\n            const osc = c.createOscillator();\n            const g = c.createGain();\n            osc.type = type;\n            osc.frequency.setValueAtTime(freq, t0);\n            if (glideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(1, glideTo), t0 + duration);\n            g.gain.setValueAtTime(0.0001, t0);\n            g.gain.exponentialRampToValueAtTime(gain, t0 + 0.01);\n            g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);\n            osc.connect(g); g.connect(master);\n            osc.start(t0); osc.stop(t0 + duration + 0.02);\n        }\n\n        function noise(duration, gain = 0.3, filterFreq = 1200, delay = 0) {\n            const c = ensureCtx();\n            if (!c) return;\n            const t0 = c.currentTime + delay;\n            const size = Math.max(1, Math.floor(c.sampleRate * duration));\n            const buffer = c.createBuffer(1, size, c.sampleRate);\n            const data = buffer.getChannelData(0);\n            for (let i = 0; i < size; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / size);\n            const src = c.createBufferSource();\n            src.buffer = buffer;\n            const filter = c.createBiquadFilter();\n            filter.type = 'lowpass'; filter.frequency.value = filterFreq;\n            const g = c.createGain();\n            g.gain.setValueAtTime(gain, t0);\n            g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);\n            src.connect(filter); filter.connect(g); g.connect(master);\n            src.start(t0);\n        }\n\n        function startAmbient() {\n            const c = ensureCtx();\n            if (!c || ambientStarted) return;\n            ambientStarted = true;\n\n            // Hlubok\u00fd hukot velitelsk\u00e9ho stanovi\u0161t\u011b (dva rozlad\u011bn\u00e9 oscil\u00e1tory)\n            const droneGain = c.createGain();\n            droneGain.gain.value = 0.05;\n            droneGain.connect(master);\n\n            [55, 55.6].forEach(f => {\n                const o = c.createOscillator();\n                o.type = 'sawtooth'; o.frequency.value = f;\n                const lp = c.createBiquadFilter();\n                lp.type = 'lowpass'; lp.frequency.value = 220;\n                o.connect(lp); lp.connect(droneGain);\n                o.start();\n            });\n\n            // Pomal\u00e9 \"d\u00fdch\u00e1n\u00ed\" hlasitosti hukotu\n            const lfo = c.createOscillator();\n            lfo.type = 'sine'; lfo.frequency.value = 0.08;\n            const lfoGain = c.createGain(); lfoGain.gain.value = 0.03;\n            lfo.connect(lfoGain); lfoGain.connect(droneGain.gain);\n            lfo.start();\n\n            // Tich\u00fd periodick\u00fd radarov\u00fd \"ping\" na pozad\u00ed\n            let pingTick = 0;\n            setInterval(() => {\n                if (muted) return;\n                pingTick++;\n                tone(1800, 0.08, 'sine', 0.02);\n            }, 4200);\n        }\n\n        function setMuted(v) {\n            muted = v;\n            try { localStorage.setItem('warroom_muted', muted ? '1' : '0'); } catch (e) {}\n            if (master) master.gain.value = muted ? 0 : 0.55;\n        }\n\n        return {\n            unlock() { ensureCtx(); startAmbient(); },\n            isMuted: () => muted,\n            toggleMuted() { setMuted(!muted); return muted; },\n\n            click()    { tone(700, 0.05, 'square', 0.10); },\n            hit()      { tone(240, 0.14, 'sawtooth', 0.22, 100); noise(0.10, 0.14, 900); },\n            graze()    { tone(320, 0.10, 'triangle', 0.15, 220); },\n            crit()     { tone(160, 0.30, 'sawtooth', 0.30, 45); noise(0.28, 0.28, 500); tone(900, 0.12, 'square', 0.12, null, 0.05); },\n            perfect()  { [700, 1000, 1400].forEach((f, i) => tone(f, 0.18, 'triangle', 0.22, null, i * 0.06)); },\n            miss()     { tone(140, 0.22, 'sine', 0.18, 55); },\n            save()     { tone(500, 0.10, 'triangle', 0.15); tone(750, 0.10, 'triangle', 0.12, null, 0.08); },\n            boom()     { noise(0.35, 0.35, 260); tone(85, 0.45, 'sine', 0.28, 35); },\n            drop()     { tone(500, 0.35, 'sine', 0.18, 220); },\n            resupply() { tone(600, 0.08, 'triangle', 0.16); tone(850, 0.10, 'triangle', 0.14, null, 0.07); },\n            buy()      { tone(880, 0.07, 'triangle', 0.18); tone(1200, 0.09, 'triangle', 0.14, null, 0.06); },\n            unlock()   { [660, 880, 1100].forEach((f, i) => tone(f, 0.16, 'triangle', 0.22, null, i * 0.09)); },\n            deny()     { tone(180, 0.12, 'square', 0.16); },\n            shake()    { tone(70, 0.25, 'sine', 0.2); },\n            victory()  { [523, 659, 784, 1046].forEach((f, i) => tone(f, 0.30, 'triangle', 0.22, null, i * 0.15)); },\n            defeat()   { [420, 360, 300, 200].forEach((f, i) => tone(f, 0.45, 'sawtooth', 0.22, f * 0.7, i * 0.22)); }\n        };\n    })();\n\n    function toggleSound() {\n        const isMuted = Sound.toggleMuted();\n        const btn = el('sound-toggle');\n        btn.textContent = isMuted ? '\ud83d\udd07' : '\ud83d\udd0a';\n        btn.classList.toggle('muted', isMuted);\n        if (!isMuted) Sound.unlock();\n    }\n\n    // Nastaven\u00ed po\u010d\u00e1te\u010dn\u00edho stavu tla\u010d\u00edtka zvuku a odem\u010den\u00ed AudioContext p\u0159i prvn\u00edm doteku/kliku\n    (function initSoundUI() {\n        const btn = el('sound-toggle');\n        if (btn && Sound.isMuted()) { btn.textContent = '\ud83d\udd07'; btn.classList.add('muted'); }\n        const unlockOnce = () => { Sound.unlock(); document.removeEventListener('pointerdown', unlockOnce); };\n        document.addEventListener('pointerdown', unlockOnce);\n    })();\n\n    // =====================================================================\n    // SKRYT\u00c1 VELITELSK\u00c1 KONZOLE (cheat menu) \u2014 aktivuje se zad\u00e1n\u00edm \"67MILUJU\"\n    // do nen\u00e1padn\u00e9ho pole \u00fapln\u011b dole na str\u00e1nce.\n    // =====================================================================\n    function checkCheatCode(value) {\n        if (value === '67MILUJU') {\n            openCheatMenu();\n            el('cheat-input').value = '';\n            el('cheat-input').blur();\n        }\n    }\n\n    function openCheatMenu() {\n        Sound.unlock();\n        Sound.perfect();\n        el('cheat-menu').style.display = 'flex';\n        let godBtn = el('cheat-god-btn');\n        if (godBtn) godBtn.innerText = `Nesmrtelnost: ${state.godMode ? 'ZAPNUTO' : 'VYPNUTO'}`;\n    }\n\n    function closeCheatMenu() {\n        Sound.click();\n        el('cheat-menu').style.display = 'none';\n    }\n\n    function cheatAction(type) {\n        Sound.buy();\n        const gameActive = el('game-screen') && el('game-screen').style.display === 'block';\n\n        if (type === 'unlockall') {\n            try {\n                let allScen = SCENARIOS.map(s => s.id);\n                let allDoc = DOCTRINES.map(d => d.id);\n                saveProgress({ unlockedScenarios: allScen, unlockedDoctrines: allDoc, highScores: {} });\n            } catch (e) { /* ignore */ }\n            showUnlockNotification('Ve\u0161ker\u00fd obsah odem\u010den. Hra se za chv\u00edli restartuje...');\n            setTimeout(() => location.reload(), 1500);\n            return;\n        }\n\n        if (!gameActive) {\n            showUnlockNotification('Nejprve zahaj ta\u017een\u00ed - pak bude konzole pln\u011b funk\u010dn\u00ed.');\n            return;\n        }\n\n        if (type === 'cp') { state.cp += 1000; }\n        else if (type === 'supplies') { state.supplies += 500; }\n        else if (type === 'front') { state.front = Math.min(state.maxFront, state.front + 200); }\n        else if (type === 'maxfront') { state.front = state.maxFront; }\n        else if (type === 'god') {\n            state.godMode = !state.godMode;\n            el('cheat-god-btn').innerText = `Nesmrtelnost: ${state.godMode ? 'ZAPNUTO' : 'VYPNUTO'}`;\n        }\n\n        updateUI();\n        checkWinLoss();\n    }\n\n    // =====================================================================\n    // INTERAKTIVN\u00cd TUTORI\u00c1L\n    // =====================================================================\n    let tutorialActive = false;\n    let tutorialStep = -1;\n    let tutorialWaitFor = null;\n\n    const TUTORIAL_STEPS = [\n        { target: '#scenarios-container', text: 'Nejprve vyber V\u00c1LE\u010cN\u00dd SC\u00c9N\u00c1\u0158. Ka\u017ed\u00fd m\u00e1 jinou mapu, tempo hry i vlastn\u00ed speci\u00e1ln\u00ed mechaniku. Pro prvn\u00ed hru doporu\u010dujeme \"Z\u00c1KLADN\u00cd FRONTA\".', hint: '\ud83d\udc49 Klikni na libovoln\u00fd sc\u00e9n\u00e1\u0159, abys pokra\u010doval.', waitFor: 'scenario' },\n        { target: '#doctrines-container', text: 'Nyn\u00ed zvol VELITELSKOU DOKTR\u00cdNU - trval\u00fd styl velen\u00ed pro cel\u00e9 ta\u017een\u00ed. Ovliv\u0148uje po\u0161kozen\u00ed, obranu i speci\u00e1ln\u00ed schopnosti.', hint: '\ud83d\udc49 Klikni na libovolnou doktr\u00ednu, abys pokra\u010doval.', waitFor: 'doctrine' },\n        { target: '#gauge-container', text: 'Toto je FRONTA - zdrav\u00ed tv\u00e9 linie. C\u00edlem ka\u017ed\u00e9ho sektoru je dotla\u010dit ji a\u017e na maximum. Pokud klesne na 0, ta\u017een\u00ed kon\u010d\u00ed.', hint: '', waitFor: null },\n        { target: '.stats-grid', text: 'Z\u00c1SOBY poh\u00e1n\u011bj\u00ed Ofenz\u00edvu, VELITELSK\u00c9 BODY (VB) financuj\u00ed speci\u00e1ln\u00ed akce a v\u00fdzkum, DEN po\u010d\u00edt\u00e1, kolik tah\u016f uplynulo.', hint: '', waitFor: null },\n        { target: '#btn-atk', text: 'OFENZ\u00cdVA stoj\u00ed Z\u00e1soby a otev\u0159e radar pro p\u0159esn\u00e9 zam\u011b\u0159en\u00ed na nep\u0159\u00edtele.', hint: '\ud83d\udc49 Zkus na ni kliknout!', waitFor: 'attack' },\n        { target: '#radar', text: 'Klikni p\u0159esn\u011b doprost\u0159ed li\u0161ty pro nejlep\u0161\u00ed mo\u017en\u00fd z\u00e1sah - \u010d\u00edm bl\u00ed\u017e st\u0159edu, t\u00edm v\u011bt\u0161\u00ed \u0161koda a bonusy.', hint: '\ud83d\udc49 Klikni kdekoliv na radar.', waitFor: 'radarClick' },\n        { target: '#btn-sup', text: 'LOGISTIKA vym\u011bn\u00ed \u010d\u00e1st Fronty za Z\u00e1soby. U\u017eite\u010dn\u00e9, kdy\u017e ti doch\u00e1z\u00ed palivo do dal\u0161\u00edch \u00fatok\u016f.', hint: '\ud83d\udc49 Zkus na ni kliknout!', waitFor: 'logistics' },\n        { target: '#command-grid', text: 'BAR\u00c1\u017d a SHOZ jsou okam\u017eit\u00e9 akce za VB, kter\u00e9 nespot\u0159ebuj\u00ed den nav\u00edc. SKILL je unik\u00e1tn\u00ed schopnost tv\u00e9ho sc\u00e9n\u00e1\u0159e.', hint: '', waitFor: null },\n        { target: '#upgrades-grid', text: 'V\u00ddZKUM trvale vylep\u0161uje tv\u00e9 jednotky za VB. Vyplat\u00ed se investovat postupn\u011b do v\u00edce sm\u011br\u016f, ne jen do jednoho.', hint: '', waitFor: null },\n        { target: '#exclusive-grid', text: 'EXKLUZIVN\u00cd TECHNOLOGIE jsou siln\u00e9, jednor\u00e1zov\u00e9 n\u00e1kupy platn\u00e9 jen pro aktu\u00e1ln\u00ed sektor - po jeho dokon\u010den\u00ed je nutn\u00e9 je koupit znovu.', hint: '', waitFor: null, final: true }\n    ];\n\n    function shouldSkipStep(idx) {\n        if (idx < 0 || idx >= TUTORIAL_STEPS.length) return false;\n        let step = TUTORIAL_STEPS[idx];\n        // Sc\u00e9n\u00e1\u0159 Ml\u00fdnek na maso \u00fato\u010d\u00ed automaticky bez radaru - krok s m\u00ed\u0159en\u00edm p\u0159esko\u010d\n        if (step.target === '#radar' && state.scenario === 'attrition') return true;\n        return false;\n    }\n\n    function startTutorial() {\n        Sound.unlock();\n        Sound.click();\n        el('tutorial-intro').style.display = 'none';\n        tutorialActive = true;\n        const gameActive = el('game-screen') && el('game-screen').style.display === 'block';\n        // Pokud je ta\u017een\u00ed ji\u017e rozehran\u00e9, p\u0159esko\u010d\u00ed se kroky v\u00fdb\u011bru sc\u00e9n\u00e1\u0159e/doktr\u00edny \n        // (aby op\u011btovn\u00e9 spu\u0161t\u011bn\u00ed tutori\u00e1lu p\u0159es tla\u010d\u00edtko \"?\" nerestartovalo rozehranou hru).\n        tutorialStep = gameActive ? 1 : -1;\n        tutorialNext();\n    }\n\n    function skipTutorial() {\n        Sound.click();\n        tutorialActive = false;\n        tutorialWaitFor = null;\n        el('tutorial-intro').style.display = 'none';\n        el('tutorial-overlay').style.display = 'none';\n        try { localStorage.setItem('warroom_tutorial_done', '1'); } catch (e) {}\n    }\n\n    function tutorialAdvanceIf(key) {\n        if (tutorialActive && tutorialWaitFor === key) {\n            tutorialWaitFor = null;\n            setTimeout(tutorialNext, 450);\n        }\n    }\n\n    function tutorialNext() {\n        if (!tutorialActive) return;\n        tutorialStep++;\n        while (shouldSkipStep(tutorialStep)) tutorialStep++;\n\n        if (tutorialStep >= TUTORIAL_STEPS.length) {\n            skipTutorial();\n            showUnlockNotification('Tutori\u00e1l dokon\u010den! Hodn\u011b \u0161t\u011bst\u00ed, veliteli. \ud83c\udf96\ufe0f');\n            return;\n        }\n\n        let step = TUTORIAL_STEPS[tutorialStep];\n        el('tutorial-overlay').style.display = 'block';\n        el('tutorial-text').innerText = step.text;\n        el('tutorial-hint').innerText = step.hint || '';\n        tutorialWaitFor = step.waitFor || null;\n\n        let nextBtn = el('tutorial-next-btn');\n        if (step.waitFor) {\n            nextBtn.classList.add('hidden-nav');\n        } else {\n            nextBtn.classList.remove('hidden-nav');\n            nextBtn.innerText = step.final ? 'Dokon\u010dit tutori\u00e1l \u2713' : 'Dal\u0161\u00ed \u203a';\n        }\n\n        positionSpotlight(step.target);\n    }\n\n    function positionSpotlight(selector) {\n        const target = document.querySelector(selector);\n        const spot = el('tutorial-spotlight');\n        if (!target || !spot) { if (spot) spot.style.opacity = '0'; return; }\n        const r = target.getBoundingClientRect();\n        spot.style.opacity = '1';\n        spot.style.top = (r.top - 6) + 'px';\n        spot.style.left = (r.left - 6) + 'px';\n        spot.style.width = (r.width + 12) + 'px';\n        spot.style.height = (r.height + 12) + 'px';\n    }\n\n    // P\u0159epo\u010d\u00edt\u00e1 polohu spotlightu p\u0159i zm\u011bn\u011b velikosti okna (mobiln\u00ed rotace atp.)\n    window.addEventListener('resize', () => {\n        if (tutorialActive && tutorialStep >= 0 && tutorialStep < TUTORIAL_STEPS.length) {\n            positionSpotlight(TUTORIAL_STEPS[tutorialStep].target);\n        }\n    });\n\n    // Automatick\u00e9 spu\u0161t\u011bn\u00ed \u00favodn\u00ed obrazovky tutori\u00e1lu p\u0159i prvn\u00ed n\u00e1v\u0161t\u011bv\u011b\n    (function initTutorial() {\n        let seen = false;\n        try { seen = localStorage.getItem('warroom_tutorial_done') === '1'; } catch (e) {}\n        if (!seen) {\n            el('tutorial-intro').style.display = 'flex';\n        }\n    })();\n\n    // =====================================================================\n    // VIZU\u00c1LN\u00cd FEEDBACK \u2014 l\u00e9taj\u00edc\u00ed \u010d\u00edsla, jiskry a z\u00e1sahov\u00e9 efekty\n    // =====================================================================\n    function floatText(text, colorClass, anchorId = 'gauge-container') {\n        const anchor = el(anchorId);\n        if (!anchor) return;\n        const rect = anchor.getBoundingClientRect();\n        const span = document.createElement('div');\n        span.className = `float-text ${colorClass}`;\n        span.textContent = text;\n        span.style.left = (rect.left + rect.width * (0.30 + Math.random() * 0.40)) + 'px';\n        span.style.top = (rect.top + rect.height * 0.5) + 'px';\n        document.body.appendChild(span);\n        setTimeout(() => span.remove(), 1250);\n    }\n\n    function spawnParticles(colorVar, count = 14, anchorId = 'gauge-container') {\n        const anchor = el(anchorId);\n        if (!anchor) return;\n        const rect = anchor.getBoundingClientRect();\n        const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;\n        for (let i = 0; i < count; i++) {\n            const p = document.createElement('div');\n            p.className = 'particle';\n            p.style.background = colorVar;\n            p.style.boxShadow = `0 0 6px ${colorVar}`;\n            p.style.left = cx + 'px';\n            p.style.top = cy + 'px';\n            p.style.opacity = '1';\n            document.body.appendChild(p);\n            const angle = Math.random() * Math.PI * 2;\n            const dist = 40 + Math.random() * 90;\n            requestAnimationFrame(() => {\n                p.style.transform = `translate(${Math.cos(angle) * dist}px, ${Math.sin(angle) * dist}px)`;\n                p.style.opacity = '0';\n            });\n            setTimeout(() => p.remove(), 650);\n        }\n    }\n\n    function flashVignette() {\n        const v = el('vignette-flash');\n        v.classList.remove('hit'); \n        void v.offsetWidth; // restart animace\n        v.classList.add('hit');\n    }\n\n    function flashPanel(good) {\n        const s = el('game-screen');\n        s.classList.remove('flash-good', 'flash-bad');\n        void s.offsetWidth;\n        s.classList.add(good ? 'flash-good' : 'flash-bad');\n    }\n\n    let anim;\n    \n    // UI upgrade mapov\u00e1n\u00ed\n    const upgradeUIMap = { \n        'supply': 'sup', 'radar': 'rad', 'dmg': 'dmg', \n        'cpGain': 'cpg', 'armor': 'arm', 'recon': 'rec',\n        'critical': 'crt', 'intel_gain': 'itg', 'engineering': 'eng'\n    };\n\n    // V\u0161echny definovan\u00e9 sc\u00e9n\u00e1\u0159e\n    const RAW_SCENARIOS = [\n        { id: 'default', tag: 'BASE', name: 'Z\u00c1KLADN\u00cd FRONTA', desc: 'Vyv\u00e1\u017een\u00e1 bojov\u00e1 linie bez zvl\u00e1\u0161tn\u00edch anom\u00e1li\u00ed.', baseMax: 500, year: 0 },\n\n        // --- NOV\u00dd SC\u00c9N\u00c1\u0158: Napoleonsk\u00e9 v\u00e1lky ---\n        { id: 'napoleon_siege', tag: 'NAPOLEON', name: 'OBL\u00c9H\u00c1N\u00cd PEVNOSTI', desc: 'Nep\u0159esn\u00e9 mu\u0161ketov\u00e9 salvy - \u00fazk\u00e1 zam\u011b\u0159ovac\u00ed z\u00f3na, ale zbran\u011b jsou levn\u00e9 a \u010dast\u00e9.', baseMax: 550, year: 1812 },\n\n        { id: 'ww1_west', tag: 'WWI', name: 'Z\u00c1PADN\u00cd FRONTA', desc: '\u00datoky nab\u00edjej\u00ed bojovou p\u0159\u00edpravu. V\u00fdhra pouze masivn\u00ed zte\u010d\u00ed.', baseMax: 600, year: 1914 },\n        { id: 'ww1_east', tag: 'WWI', name: 'V\u00ddCHODN\u00cd FRONTA', desc: 'Z\u00e1sobov\u00e1n\u00ed kolabuje. Logistika nese minimum z\u00e1sob.', baseMax: 450, year: 1914 },\n        { id: 'ww2_blitz', tag: 'WWII', name: 'BLESKOV\u00c1 V\u00c1LKA', desc: 'Hybnost je kl\u00ed\u010dem k v\u00edt\u011bzstv\u00ed. Minut\u00ed t\u011b fat\u00e1ln\u011b ochrom\u00ed.', baseMax: 400, year: 1940 },\n        { id: 'ww2_pacific', tag: 'WWII', name: 'PACIFIK', desc: 'Ustoupit do mo\u0159e nelze. Velmi rychl\u00e9 a dynamick\u00e9 sektory.', baseMax: 200, year: 1941 },\n        { id: 'winter_war', tag: 'WWII', name: 'ZIMN\u00cd V\u00c1LKA', desc: 'Extr\u00e9mn\u00ed tlak sov\u011btsk\u00fdch vojsk. Nutn\u00e1 rychl\u00e1 sabot\u00e1\u017e.', baseMax: 500, year: 1939 },\n\n        // --- NOV\u00dd SC\u00c9N\u00c1\u0158: Korejsk\u00e1 v\u00e1lka ---\n        { id: 'korea', tag: 'COLD WAR', name: 'KOREJSK\u00c1 V\u00c1LKA', desc: 'Drtiv\u00e9 lidsk\u00e9 vlny ze severu. Leteck\u00e9 shozy OSN nesou o polovinu v\u00edce z\u00e1sob.', baseMax: 600, year: 1950 },\n\n        { id: 'guerilla', tag: 'COLD WAR', name: 'ODBOJ', desc: 'Z\u00e1soby jsou kradeny p\u0159\u00edmo z t\u011bl nep\u0159\u00e1tel p\u0159i p\u0159esn\u00fdch z\u00e1saz\u00edch.', baseMax: 350, year: 1960 },\n        { id: 'vietnam', tag: 'COLD WAR', name: 'VIETNAM', desc: 'Neviditeln\u00e1 fronta skryt\u00e1 v d\u017eungli, dokud nepou\u017eije\u0161 Napalm.', baseMax: 450, year: 1965 },\n\n        // --- NOV\u00dd SC\u00c9N\u00c1\u0158: Jomkipursk\u00e1 v\u00e1lka ---\n        { id: 'yom_kippur', tag: 'COLD WAR', name: 'JOM KIPUR', desc: 'N\u00e1hl\u00fd \u00fatok o Sv\u00e1tku sm\u00ed\u0159en\u00ed. Prvn\u00ed 3 dny je tlak nep\u0159\u00edtele dvojn\u00e1sobn\u00fd, pak opadne.', baseMax: 500, year: 1973 },\n\n        // --- NOV\u00dd SC\u00c9N\u00c1\u0158: Falklandsk\u00e1 v\u00e1lka ---\n        { id: 'falklands', tag: 'NAVAL', name: 'FALKLANDY', desc: 'Z\u00e1sobovac\u00ed linie t\u00e1hnou p\u0159es cel\u00fd oce\u00e1n (\u00fatok stoj\u00ed 2 Z\u00e1soby), ale p\u0159esn\u00e9 z\u00e1sahy krv\u00ed o +10% vy\u0161\u0161\u00ed \u0161anci na kritick\u00fd z\u00e1sah.', baseMax: 400, year: 1982 },\n\n        { id: 'desert', tag: 'GULF WAR', name: 'POU\u0160TN\u00cd BOU\u0158E', desc: 'Vyprahl\u00e9 \u00fazem\u00ed. Ofenz\u00edva stoj\u00ed dvojn\u00e1sobek z\u00e1sob.', baseMax: 600, year: 1991 },\n        { id: 'blockade', tag: 'NAVAL', name: 'N\u00c1MO\u0158N\u00cd BLOK\u00c1DA', desc: 'Extr\u00e9mn\u011b drah\u00fd \u00fatok (3 Z\u00e1soby). Logistika hraje prim\u00e1rn\u00ed roli.', baseMax: 600, year: 2008 },\n        { id: 'modern_ew', tag: 'MODERN', name: 'KYBER V\u00c1LKA', desc: 'Permanentn\u00ed elektromagnetick\u00e9 ru\u0161en\u00ed drasticky zrychluje radar.', baseMax: 500, year: 2015 },\n        { id: 'urban', tag: 'MODERN', name: 'M\u011aSTSK\u00dd BOJ', desc: 'Dlouh\u00fd sektor pln\u00fd ruin. permanentn\u00ed 50% postih k po\u0161kozen\u00ed.', baseMax: 1000, year: 2018 },\n        { id: 'zombie', tag: 'HORROR', name: 'ZOMBIE N\u00c1KAZA', desc: 'Minut\u00ed zved\u00e1 hladinu mutace. Ka\u017ed\u00fd omyl trvale zesiluje tlak.', baseMax: 500, year: 2020 },\n        { id: 'drone', tag: 'MODERN', name: 'DRONOV\u00c1 V\u00c1LKA', desc: 'Vzdu\u0161n\u00e9 shozy a klasick\u00e1 artilerie jsou kompletn\u011b odpojeny.', baseMax: 400, year: 2022 },\n        { id: 'attrition', tag: 'ALT-HIST', name: 'ML\u00ddNEK NA MASO', desc: 'Operuje\u0161 naslepo bez radaru. \u010cist\u00e1 matematick\u00e1 simulace boje.', baseMax: 700, year: 2026 },\n        { id: 'cyber_rebel', tag: 'SCI-FI', name: 'KYBER POVST\u00c1N\u00cd', desc: 'Radar se chov\u00e1 nep\u0159edv\u00eddateln\u011b a kmit\u00e1 chaoticky. Z\u00e1sahy daj\u00ed +20 VB.', baseMax: 500, year: 2030 },\n        { id: 'nuke_winter', tag: 'ALT-HIST', name: 'NUKLE\u00c1RN\u00cd ZIMA', desc: 'Extr\u00e9mn\u00ed mr\u00e1z ti bere -1 Z\u00e1sobu ka\u017ed\u00fd tah. Tlak nep\u0159\u00edtele je polovi\u010dn\u00ed.', baseMax: 550, year: 2035 },\n        { id: 'space', tag: 'SCI-FI', name: 'ORBIT\u00c1LN\u00cd V\u00c1LKA', desc: 'Z\u00e1vratn\u00e9 kosmick\u00e9 tempo radaru. Kdo na sekundu zav\u00e1h\u00e1, zem\u0159e.', baseMax: 400, year: 2150 },\n        { id: 'alien_inv', tag: 'SCI-FI', name: 'MIMOZEMSK\u00c1 INVAZE', desc: 'Mimozem\u0161\u0165an\u00e9 maj\u00ed energetick\u00fd \u0161t\u00edt, kter\u00fd pohlcuje po\u0161kozen\u00ed a dob\u00edj\u00ed se.', baseMax: 650, year: 2200 },\n\n        // --- NOV\u00dd SC\u00c9N\u00c1\u0158: Marsovsk\u00e1 kolonie ---\n        { id: 'mars_colony', tag: 'SCI-FI', name: 'MARSOVSK\u00c1 KOLONIE', desc: 'N\u00edzk\u00e1 gravitace posiluje v\u00fdbu\u0161niny (+10% Dmg), ale nedostatek zdroj\u016f sni\u017euje zisk Z\u00e1sob (-20%).', baseMax: 700, year: 2250 }\n    ];\n\n    // Sc\u00e9n\u00e1\u0159e jsou v\u017edy se\u0159azeny chronologicky (od nejstar\u0161\u00edho konfliktu po nejnov\u011bj\u0161\u00ed / sci-fi budoucnost).\n    // \"default\" z\u016fst\u00e1v\u00e1 v\u017edy prvn\u00ed jako z\u00e1kladn\u00ed v\u00fdcvikov\u00fd sc\u00e9n\u00e1\u0159 bez pevn\u00e9ho data.\n    const SCENARIOS = RAW_SCENARIOS.slice().sort((a, b) => {\n        if (a.id === 'default') return -1;\n        if (b.id === 'default') return 1;\n        return a.year - b.year;\n    });\n\n    // V\u0161echny definovan\u00e9 doktr\u00edny\n    const DOCTRINES = [\n        { id: 'blitz', name: '\u00daTO\u010cN\u00c1 - Blitz', desc: '+30% Dmg. Tlak +15%. Unik\u00e1tn\u00ed: Kritick\u00fd z\u00e1sah nestoj\u00ed Z\u00e1soby.', unlockInfo: 'Z\u00e1kladn\u00ed doktr\u00edna' },\n        { id: 'fortress', name: 'OBRANN\u00c1 - Pevnost', desc: 'Tlak sn\u00ed\u017een o -20%. Unik\u00e1tn\u00ed: Max Fronta zv\u00fd\u0161ena o +20%.', unlockInfo: 'Z\u00e1kladn\u00ed doktr\u00edna' },\n        { id: 'intel', name: 'ZPRAVODAJSK\u00c1 - Intel', desc: 'Crit \u0161ance +25%. Dmg -15%. Unik\u00e1tn\u00ed: Absolutn\u00ed st\u0159ed radaru = +20 VB.', unlockInfo: 'Dos\u00e1hni Sektoru 5 v Bleskov\u00e9 v\u00e1lce' },\n        { id: 'quartermaster', name: 'LOGISTICK\u00c1 - Z\u00e1soby', desc: 'Startuje\u0161 s 20 Z. Unik\u00e1tn\u00ed: M\u00e1\u0161-li pod 5 Z, logistika nestoj\u00ed \u017e\u00e1dnou Frontu.', unlockInfo: 'Dos\u00e1hni Sektoru 5 ve V\u00fdchodn\u00ed front\u011b / Blok\u00e1d\u011b' },\n        { id: 'tech', name: 'TECHNOLOGICK\u00c1 - R&D', desc: 'V\u00fdzkumy o 25% levn\u011bj\u0161\u00ed. Unik\u00e1tn\u00ed: Koup\u011b v\u00fdzkumu p\u0159id\u00e1 +10 Fronty.', unlockInfo: 'Dos\u00e1hni Sektoru 5 v Kyber v\u00e1lce' },\n        { id: 'artillery', name: 'D\u011aLOST\u0158ELECK\u00c1 - Shock', desc: 'Skilly o 25% levn\u011bj\u0161\u00ed. Crit jen 5%. Unik\u00e1tn\u00ed: Bar\u00e1\u017e ochrom\u00ed nep\u0159\u00edtele na 2 dny.', unlockInfo: 'Dos\u00e1hni Sektoru 5 v Z\u00e1padn\u00ed front\u011b' },\n        { id: 'partisan', name: 'ODBOJOV\u00c1 - Partyz\u00e1n', desc: '+30% zisk z logistiky. Dmg -20%. Unik\u00e1tn\u00ed: +50% Dmg do ochromen\u00e9ho c\u00edle.', unlockInfo: 'Dos\u00e1hni Sektoru 5 v Odboji / Vietnamu' },\n        { id: 'propaganda', name: 'POLITICK\u00c1 - Osv\u011bta', desc: '+25% zisk v\u0161ech VB. Tlak +15%. Unik\u00e1tn\u00ed: Ka\u017ed\u00fd 10. den se linie vyl\u00e9\u010d\u00ed o +50 bod\u016f.', unlockInfo: 'Dos\u00e1hni Sektoru 10 v Z\u00e1kladn\u00ed front\u011b' },\n        { id: 'fanatic', name: 'FANATICK\u00c1 - V\u00edra', desc: 'Pod 35% HP ud\u011bl\u00ed\u0161 +50% Dmg. Unik\u00e1tn\u00ed: Last Stand. Zabr\u00e1n\u00ed prvn\u00ed smrti v sektoru.', unlockInfo: 'Dos\u00e1hni Sektoru 5 v Zombie n\u00e1kaze / Ml\u00fdnku' },\n        \n        // Nov\u00e9 doktr\u00edny\n        { id: 'fleet', name: 'N\u00c1MO\u0158N\u00cd - Fleet', desc: 'V\u00fdnos logistiky +40%. P\u0159esn\u00fd z\u00e1sah v c\u00edlov\u00e9 z\u00f3n\u011b m\u00e1 30% \u0161anci vr\u00e1tit pou\u017eitou z\u00e1sobu.', unlockInfo: 'Dos\u00e1hni Sektoru 5 v Pacifiku / Blok\u00e1d\u011b' },\n        { id: 'mercenary', name: '\u017dOLD\u00c1CK\u00c1 - Kontrakt', desc: 'Hospod\u00e1\u0159sk\u00e1 doktr\u00edna. Ka\u017ed\u00fd den z\u00edsk\u00e1\u0161 extra +2 VB za ka\u017edou zb\u00fdvaj\u00edc\u00ed jednotku Z\u00e1sob.', unlockInfo: 'Dos\u00e1hni Sektoru 5 v Pou\u0161tn\u00ed bou\u0159i' },\n        { id: 'chemical', name: 'CHEMICK\u00c1 - Toxic', desc: 'Ka\u017ed\u00fd \u00fasp\u011b\u0161n\u00fd \u00fatok do nep\u0159\u00edtele m\u00e1 15% \u0161anci, \u017ee ho okam\u017eit\u011b ochrom\u00ed na 1 kolo.', unlockInfo: 'Dos\u00e1hni Sektoru 5 v Kyber povst\u00e1n\u00ed / Nukle\u00e1rn\u00ed zim\u011b' }\n    ];\n\n    // ===== SYNERGIE SC\u00c9N\u00c1\u0158 + DOKTR\u00cdNA =====\n    // V\u017edy jen POZITIVN\u00cd bonus za tematicky vhodnou kombinaci - nikdy postih za \"\u0161patnou\" volbu.\n    const SYNERGIES = {\n        'guerilla|partisan':     { label: 'PARTYZ\u00c1NSK\u00c1 TAKTIKA', type: 'supply',    value: 0.20 },\n        'vietnam|partisan':      { label: 'PARTYZ\u00c1NSK\u00c1 TAKTIKA', type: 'crit',      value: 0.15 },\n        'ww1_west|artillery':    { label: 'D\u011aLOST\u0158ELECK\u00c1 \u0160KOLA', type: 'skillCost', value: -0.15 },\n        'urban|fortress':        { label: 'OPEVN\u011aN\u00c9 ULICE',      type: 'maxFrontOnce', value: 0.15 },\n        'ww2_pacific|fleet':     { label: 'N\u00c1MO\u0158N\u00cd PODPORA',     type: 'supply',    value: 0.20 },\n        'blockade|fleet':        { label: 'N\u00c1MO\u0158N\u00cd PODPORA',     type: 'supply',    value: 0.20 },\n        'falklands|fleet':       { label: 'N\u00c1MO\u0158N\u00cd PODPORA',     type: 'crit',      value: 0.15 },\n        'modern_ew|tech':        { label: 'VYSP\u011aL\u00c1 TECHNIKA',    type: 'dmg',       value: 0.10 },\n        'cyber_rebel|tech':      { label: 'VYSP\u011aL\u00c1 TECHNIKA',    type: 'dmg',       value: 0.10 },\n        'zombie|chemical':       { label: 'TOXICK\u00c1 SYNERGIE',    type: 'dmg',       value: 0.10 },\n        'nuke_winter|chemical':  { label: 'TOXICK\u00c1 SYNERGIE',    type: 'push',      value: -0.15 },\n        'desert|mercenary':      { label: 'V\u00c1LE\u010cN\u00dd OBCHODN\u00cdK',   type: 'cp',        value: 0.10 },\n        'blockade|mercenary':    { label: 'V\u00c1LE\u010cN\u00dd OBCHODN\u00cdK',   type: 'cp',        value: 0.10 },\n        'napoleon_siege|intel':  { label: 'POLN\u00cd DALEKOHLEDY',   type: 'radar',     value: 0.20 },\n        'korea|blitz':           { label: 'PR\u016eLOM FRONTY',       type: 'dmg',       value: 0.10 },\n        'yom_kippur|propaganda': { label: 'N\u00c1RODN\u00cd MOBILIZACE',  type: 'cp',        value: 0.15 },\n        'attrition|fanatic':     { label: 'FANATICK\u00c1 V\u00cdRA',      type: 'skillCost', value: -0.15 }\n    };\n\n    function getSynergy() {\n        return SYNERGIES[state.scenario + '|' + state.doctrine] || null;\n    }\n    function getSynergyBonus(type) {\n        let syn = getSynergy();\n        return (syn && syn.type === type) ? syn.value : 0;\n    }\n\n    let state = {\n        scenario: '', doctrine: '',\n        front: 250, maxFront: 500, supplies: 10, cp: 0, day: 1, sector: 1,\n        baseEnemyPush: 6, isAiming: false, currentPointerPos: 50, enemyStunned: 0,\n        exclusiveBought1: false, exclusiveBought2: false, exclusiveBought3: false,\n        gamePaused: false, fanaticUsed: false, alienShield: 0, godMode: false,\n        \n        ww1_trenchPrep: 0, ww2_momentumPlayer: 0, ww2_momentumEnemy: 0,\n        viet_revealed: 0, modern_counterTimer: 0, zombie_mutation: 0,\n        \n        costArt: 30, costAir: 20, costSkill: 0,\n\n        upgrades: {\n            supply: { name: 'Logistika', level: 1, cost: 15 },\n            radar:  { name: 'Optika',    level: 1, cost: 25 },\n            dmg:    { name: 'Zbran\u011b',    level: 1, cost: 40 },\n            cpGain: { name: 'Velen\u00ed',    level: 1, cost: 20 },\n            armor:  { name: 'Panc\u00ed\u0159',    level: 1, cost: 30 }, \n            recon:  { name: 'Pr\u016fzkum',   level: 1, cost: 35 },\n            \n            // 3 Nov\u00e9 glob\u00e1ln\u00ed v\u00fdzkumy\n            critical: { name: 'Kritika', level: 1, cost: 30 },\n            intel_gain: { name: 'Rozv\u011bdka', level: 1, cost: 25 },\n            engineering: { name: '\u017denist\u00e9', level: 1, cost: 35 }\n        }\n    };\n\n    // --- PROGRESS SYST\u00c9M (LOCAL STORAGE) ---\n    function loadProgress() {\n        let saved = null;\n        try { saved = localStorage.getItem('warroom_frontlines_save_v1'); } catch (e) { saved = null; }\n        if (saved) {\n            try {\n                let parsed = JSON.parse(saved);\n                if (!parsed.unlockedScenarios) parsed.unlockedScenarios = ['default'];\n                if (!parsed.unlockedDoctrines) parsed.unlockedDoctrines = ['blitz', 'fortress'];\n                if (!parsed.highScores) parsed.highScores = {};\n                return parsed;\n            } catch (e) {\n                console.error(\"Chyba p\u0159i \u010dten\u00ed ulo\u017een\u00e9ho progressu.\");\n            }\n        }\n        return {\n            unlockedScenarios: ['default'],\n            unlockedDoctrines: ['blitz', 'fortress'],\n            highScores: {}\n        };\n    }\n\n    function saveProgress(prog) {\n        try {\n            localStorage.setItem('warroom_frontlines_save_v1', JSON.stringify(prog));\n        } catch (e) {\n            console.error(\"Nepoda\u0159ilo se ulo\u017eit postup.\", e);\n        }\n    }\n\n    function resetSave() {\n        if (confirm(\"Opravdu chcete kompletn\u011b vymazat ve\u0161ker\u00fd dosavadn\u00ed postup kampan\u011b?\")) {\n            try { localStorage.removeItem('warroom_frontlines_save_v1'); } catch (e) { /* ignore */ }\n            location.reload();\n        }\n    }\n\n    function showUnlockNotification(text) {\n        Sound.unlock();\n        let t = document.createElement('div');\n        t.className = 'toast-notification';\n        t.innerHTML = `<div class=\"toast-title\">Bojov\u00e9 Hl\u00e1\u0161en\u00ed HQ</div><div class=\"toast-body\">${text}</div>`;\n        document.body.appendChild(t);\n        setTimeout(() => t.classList.add('active'), 100);\n        setTimeout(() => {\n            t.classList.remove('active');\n            setTimeout(() => t.remove(), 600);\n        }, 4500);\n    }\n\n    function getScenarioName(id) {\n        let sc = SCENARIOS.find(s => s.id === id);\n        return sc ? sc.name : id.toUpperCase();\n    }\n\n    function checkSectorUnlockProgression() {\n        let prog = loadProgress();\n        let changed = false;\n        \n        let currentMax = prog.highScores[state.scenario] || 1;\n        if (state.sector > currentMax) {\n            prog.highScores[state.scenario] = state.sector;\n            changed = true;\n        }\n\n        // 1. Postupn\u00e9 odemyk\u00e1n\u00ed sc\u00e9n\u00e1\u0159\u016f (Sektor 10 p\u0159edchoz\u00edho sc\u00e9n\u00e1\u0159e odemkne dal\u0161\u00ed v po\u0159ad\u00ed)\n        for (let i = 0; i < SCENARIOS.length - 1; i++) {\n            let cur = SCENARIOS[i].id;\n            let next = SCENARIOS[i+1].id;\n            \n            // Pokud hr\u00e1\u010d dos\u00e1hl Sektoru 10 v aktu\u00e1ln\u00edm a dal\u0161\u00ed je\u0161t\u011b nem\u00e1 odem\u010den\u00fd\n            if (state.scenario === cur && state.sector >= 10 && !prog.unlockedScenarios.includes(next)) {\n                prog.unlockedScenarios.push(next);\n                showUnlockNotification(`\ud83d\udd13 NOV\u00c1 FRONTA ODEM\u010cENA:<br>${getScenarioName(next)}`);\n                changed = true;\n            }\n        }\n\n        // 2. Podm\u00ednkov\u00e9 odemyk\u00e1n\u00ed doktr\u00edn na z\u00e1klad\u011b odehran\u00fdch sektor\u016f\n        if (state.scenario === 'ww2_blitz' && state.sector >= 5 && !prog.unlockedDoctrines.includes('intel')) {\n            prog.unlockedDoctrines.push('intel');\n            showUnlockNotification(\"\ud83e\udde0 ODEM\u010cENA DOKTR\u00cdNA:<br>Zpravodajsk\u00e1 (Intel)\");\n            changed = true;\n        }\n        if ((state.scenario === 'ww1_east' || state.scenario === 'blockade') && state.sector >= 5 && !prog.unlockedDoctrines.includes('quartermaster')) {\n            prog.unlockedDoctrines.push('quartermaster');\n            showUnlockNotification(\"\ud83d\udce6 ODEM\u010cENA DOKTR\u00cdNA:<br>Logistick\u00e1 (Z\u00e1soby)\");\n            changed = true;\n        }\n        if (state.scenario === 'modern_ew' && state.sector >= 5 && !prog.unlockedDoctrines.includes('tech')) {\n            prog.unlockedDoctrines.push('tech');\n            showUnlockNotification(\"\u2699\ufe0f ODEM\u010cENA DOKTR\u00cdNA:<br>Technologick\u00e1 (R&D)\");\n            changed = true;\n        }\n        if (state.scenario === 'ww1_west' && state.sector >= 5 && !prog.unlockedDoctrines.includes('artillery')) {\n            prog.unlockedDoctrines.push('artillery');\n            showUnlockNotification(\"\ud83d\udca5 ODEM\u010cENA DOKTR\u00cdNA:<br>D\u011blost\u0159eleck\u00e1 (Shock)\");\n            changed = true;\n        }\n        if ((state.scenario === 'guerilla' || state.scenario === 'vietnam') && state.sector >= 5 && !prog.unlockedDoctrines.includes('partisan')) {\n            prog.unlockedDoctrines.push('partisan');\n            showUnlockNotification(\"\ud83c\udf32 ODEM\u010cENA DOKTR\u00cdNA:<br>Odbojov\u00e1 (Partyz\u00e1n)\");\n            changed = true;\n        }\n        if (state.scenario === 'default' && state.sector >= 10 && !prog.unlockedDoctrines.includes('propaganda')) {\n            prog.unlockedDoctrines.push('propaganda');\n            showUnlockNotification(\"\ud83d\udce2 ODEM\u010cENA DOKTR\u00cdNA:<br>Politick\u00e1 (Osv\u011bta)\");\n            changed = true;\n        }\n        if ((state.scenario === 'zombie' || state.scenario === 'attrition') && state.sector >= 5 && !prog.unlockedDoctrines.includes('fanatic')) {\n            prog.unlockedDoctrines.push('fanatic');\n            showUnlockNotification(\"\u2623\ufe0f ODEM\u010cENA DOKTR\u00cdNA:<br>Fanatick\u00e1 (V\u00edra)\");\n            changed = true;\n        }\n        if ((state.scenario === 'ww2_pacific' || state.scenario === 'blockade') && state.sector >= 5 && !prog.unlockedDoctrines.includes('fleet')) {\n            prog.unlockedDoctrines.push('fleet');\n            showUnlockNotification(\"\u2693 ODEM\u010cENA DOKTR\u00cdNA:<br>N\u00e1mo\u0159n\u00ed (Fleet)\");\n            changed = true;\n        }\n        if (state.scenario === 'desert' && state.sector >= 5 && !prog.unlockedDoctrines.includes('mercenary')) {\n            prog.unlockedDoctrines.push('mercenary');\n            showUnlockNotification(\"\ud83d\udcb5 ODEM\u010cENA DOKTR\u00cdNA:<br>\u017dold\u00e1ck\u00e1 (Contract)\");\n            changed = true;\n        }\n        if ((state.scenario === 'cyber_rebel' || state.scenario === 'nuke_winter') && state.sector >= 5 && !prog.unlockedDoctrines.includes('chemical')) {\n            prog.unlockedDoctrines.push('chemical');\n            showUnlockNotification(\"\ud83e\uddea ODEM\u010cENA DOKTR\u00cdNA:<br>Chemick\u00e1 (Toxic)\");\n            changed = true;\n        }\n\n        if (changed) saveProgress(prog);\n    }\n\n    // --- DYNAMICK\u00c9 VYSTAVEN\u00cd OBRAZOVEK WIZARDU ---\n    function initWizards() {\n        let prog = loadProgress();\n        \n        // Zobrazen\u00ed sc\u00e9n\u00e1\u0159\u016f\n        let sCont = el('scenarios-container');\n        sCont.innerHTML = '';\n        SCENARIOS.forEach(sc => {\n            let isUnlocked = prog.unlockedScenarios.includes(sc.id);\n            let card = document.createElement('div');\n            card.className = `card ${isUnlocked ? '' : 'locked-card'}`;\n            if (isUnlocked) {\n                card.onclick = () => setScenario(sc.id);\n            }\n            \n            let badgeBg = '#4b5563';\n            if (sc.tag === 'WWI') badgeBg = '#d97706';\n            if (sc.tag === 'WWII') badgeBg = '#dc2626';\n            if (sc.tag === 'COLD WAR') badgeBg = '#16a34a';\n            if (sc.tag === 'MODERN') badgeBg = '#7c3aed';\n            if (sc.tag === 'GULF WAR') badgeBg = '#ea580c';\n            if (sc.tag === 'HORROR') badgeBg = '#65a30d';\n            if (sc.tag === 'SCI-FI') badgeBg = '#0891b2';\n            if (sc.tag === 'NAVAL') badgeBg = '#2563eb';\n            if (sc.tag === 'ALT-HIST') badgeBg = '#831843';\n            if (sc.tag === 'NAPOLEON') badgeBg = '#92400e';\n            \n            card.innerHTML = `\n                <span class=\"scenario-tag\" style=\"background: ${badgeBg};\">${sc.tag}</span>\n                <h4 class=\"${isUnlocked ? 't-white' : 't-gray'}\">${sc.name} ${sc.year > 0 ? `<span class=\"scenario-year\">${sc.year}</span>` : ''}</h4>\n                <small>${isUnlocked ? sc.desc : `<span class=\"t-red\">\ud83d\udd12 UZAM\u010cENO</span><br>Mus\u00edte dokon\u010dit Sektor 10 v p\u0159edchoz\u00edm sc\u00e9n\u00e1\u0159i.`}</small>\n            `;\n            sCont.appendChild(card);\n        });\n\n        // Zobrazen\u00ed doktr\u00edn\n        let dCont = el('doctrines-container');\n        dCont.innerHTML = '';\n        DOCTRINES.forEach(doc => {\n            let isUnlocked = prog.unlockedDoctrines.includes(doc.id);\n            let card = document.createElement('div');\n            card.className = `card ${isUnlocked ? '' : 'locked-card'}`;\n            if (isUnlocked) {\n                card.onclick = () => setDoctrine(doc.id);\n            }\n            \n            card.innerHTML = `\n                <h4 class=\"${isUnlocked ? 't-green' : 't-gray'}\">${doc.name}</h4>\n                <small>${isUnlocked ? doc.desc : `<span class=\"t-red\">\ud83d\udd12 ZAM\u010cENO</span><br>Podm\u00ednka: ${doc.unlockInfo}`}</small>\n            `;\n            dCont.appendChild(card);\n        });\n    }\n\n    // --- CENTR\u00c1LN\u00cd MULTIPLIK\u00c1TORY ---\n    function getDmgMult() {\n        let m = 1.0 + ((state.upgrades.dmg.level - 1) * 0.20); \n        if (state.doctrine === 'blitz') m += 0.30;\n        if (state.doctrine === 'intel') m -= 0.15;\n        if (state.doctrine === 'partisan') m -= 0.20;\n        if (state.scenario === 'urban' && !state.exclusiveBought1) m -= 0.50;\n        if (state.scenario === 'space' && state.exclusiveBought1) m += 0.50;\n        if (state.scenario === 'ww2_pacific' && state.exclusiveBought2) m += 0.40;\n        if (state.scenario === 'drone' && state.exclusiveBought1) m += 0.35;\n        if (state.scenario === 'ww2_blitz' && state.ww2_momentumPlayer > 0) m += (state.ww2_momentumPlayer * 0.20);\n        if (state.scenario === 'attrition' && state.exclusiveBought3) m += 0.60; \n        if (state.scenario === 'ww2_blitz' && state.exclusiveBought3) m += 0.50;\n        if (state.scenario === 'mars_colony') m += 0.10;\n        if (state.scenario === 'mars_colony' && state.exclusiveBought2) m += 0.25;\n        if (state.scenario === 'yom_kippur' && state.exclusiveBought2 && state.day <= 3) m += 0.30;\n        m += getSynergyBonus('dmg');\n        return Math.max(0.1, m);\n    }\n\n    function getSupplyMult() {\n        let m = 1.0 + ((state.upgrades.supply.level - 1) * 0.30); \n        if (state.doctrine === 'partisan') m += 0.30;\n        if (state.doctrine === 'fleet') m += 0.40;\n        if (state.scenario === 'ww1_east' && state.exclusiveBought2) m += 0.50;\n        if (state.scenario === 'urban' && state.exclusiveBought2) m += 0.50;\n        if (state.scenario === 'blockade') {\n            if (state.exclusiveBought1) m *= 3.0;\n            else m *= 1.5; \n        }\n        if (state.scenario === 'mars_colony') {\n            m -= 0.20;\n            if (state.exclusiveBought1) m += 0.40;\n        }\n        if (state.scenario === 'yom_kippur' && state.exclusiveBought3) m += 0.50;\n        m += getSynergyBonus('supply');\n        return Math.max(0.1, m);\n    }\n\n    function getCpMult() {\n        let m = 1.0 + ((state.upgrades.cpGain.level - 1) * 0.20); \n        if (state.doctrine === 'propaganda') m += 0.25;\n        if (state.scenario === 'attrition' && state.exclusiveBought2) m += 1.0; \n        if (state.scenario === 'guerilla' && state.exclusiveBought3) m += 0.40;\n        if (state.scenario === 'korea' && state.exclusiveBought3) m += 0.25;\n        if (state.scenario === 'mars_colony' && state.exclusiveBought3) m += 0.35;\n        m += getSynergyBonus('cp');\n        return Math.max(0.1, m);\n    }\n\n    function getRadarWidth() {\n        let base = 10; \n        let m = 1.0 + ((state.upgrades.radar.level - 1) * 0.25); \n        if (state.doctrine === 'intel') m += 0.50;\n        if (state.scenario === 'winter_war' && state.exclusiveBought1) m += 0.50;\n        if (state.scenario === 'desert' && state.exclusiveBought2) m += 0.50;\n        if (state.scenario === 'cyber_rebel' && state.exclusiveBought3) m += 0.40;\n        if (state.scenario === 'napoleon_siege') {\n            m -= 0.30;\n            if (state.exclusiveBought2) m += 0.40;\n        }\n        m += getSynergyBonus('radar');\n        return Math.min(100, base * m);\n    }\n\n    // MASIVN\u00cd BUFF PR\u016eZKUMU (RECON)\n    function getPassiveCp() {\n        if (state.upgrades.recon.level === 1) return 0;\n        let base = 15; \n        let m = 1.0 + ((state.upgrades.recon.level - 2) * 0.70); \n        // Pasiv generuje fixn\u00ed z\u00e1klad + \u0161k\u00e1luje se s aktu\u00e1ln\u00edm dnem konfliktu\n        let currentPassive = Math.floor(base * m) + Math.floor(state.day * 1.5);\n        \n        if (state.scenario === 'space' && state.exclusiveBought3) {\n            currentPassive += (state.upgrades.recon.level * 15);\n        }\n        return currentPassive;\n    }\n\n    function getScenarioBaseMaxFront(scen) {\n        let target = SCENARIOS.find(s => s.id === scen);\n        return target ? target.baseMax : 500;\n    }\n\n    // --- UNIK\u00c1TN\u00cd TECHNOLOGIE (Nyn\u00ed 3 pro ka\u017ed\u00fd sc\u00e9n\u00e1\u0159) ---\n    function getExclusive1() {\n        switch(state.scenario) {\n            case 'default': return { name: \"POLN\u00cd NEMOCNICE\", cost: 300, desc: \"Trvale sni\u017euje denn\u00ed tlak nep\u0159\u00edtele o -15%.\" };\n            case 'ww1_west': return { name: \"\u00daDERN\u00c9 ODD\u00cdLY\", cost: 400, desc: \"Zte\u010d n\u00e1sob\u00ed nasb\u00edranou p\u0159\u00edpravu 2.5x.\" };\n            case 'ww1_east': return { name: \"DRANCOV\u00c1N\u00cd\", cost: 350, desc: \"Rekv\u00edrov\u00e1n\u00ed stoj\u00ed jen -5 FR (m\u00edsto -15).\" };\n            case 'ww2_blitz': return { name: \"MOTORIZACE\", cost: 450, desc: \"Minut\u00ed c\u00edle ti nesma\u017ee hybnost, jen ji sn\u00ed\u017e\u00ed o 1.\" };\n            case 'ww2_pacific': return { name: \"V\u00ddSADKOV\u00c1 PLAVIDLA\", cost: 500, desc: \"Zisk z\u00e1sob za dobyt\u00fd ostrov zdvojn\u00e1soben (+100%).\" };\n            case 'winter_war': return { name: \"B\u00cdL\u00c1 SMRT\", cost: 350, desc: \"Trvale roz\u0161i\u0159uje z\u00f3nu radaru o +50%.\" };\n            case 'vietnam': return { name: \"AGENT ORANGE\", cost: 400, desc: \"Napalm odhal\u00ed frontu na 6 dn\u00ed.\" };\n            case 'modern_ew': return { name: \"KVANTOV\u00dd RADAR\", cost: 500, desc: \"Zpomal\u00ed rychlost ru\u0161en\u00e9ho radaru o 30%.\" };\n            case 'desert': return { name: \"MOBILN\u00cd Z\u00c1SOBOV\u00c1N\u00cd\", cost: 600, desc: \"Ofenz\u00edva stoj\u00ed u\u017e jen 1 Z\u00e1sobu.\" };\n            case 'urban': return { name: \"T\u011a\u017dK\u00c1 TECHNIKA\", cost: 450, desc: \"Zru\u0161\u00ed penalizaci -50% po\u0161kozen\u00ed v ruin\u00e1ch.\" };\n            case 'guerilla': return { name: \"PODZEMN\u00cd S\u00cd\u0164\", cost: 350, desc: \"Kr\u00e1de\u017e z\u00e1sob p\u0159i z\u00e1sahu je zdvojn\u00e1sobena (x2).\" };\n            case 'drone': return { name: \"AUTONOMN\u00cd ROJE\", cost: 500, desc: \"Zvy\u0161uje celkov\u00e9 po\u0161kozen\u00ed o +35%.\" };\n            case 'zombie': return { name: \"VIROV\u00c1 ANAL\u00ddZA\", cost: 450, desc: \"Ka\u017ed\u00fd P\u0158ESN\u00dd z\u00e1sah vyl\u00e9\u010d\u00ed -1 \u00farove\u0148 Mutace.\" };\n            case 'space': return { name: \"ASISTENCE AI\", cost: 550, desc: \"Radar se zpomal\u00ed. +50% k po\u0161kozen\u00ed.\" };\n            case 'blockade': return { name: \"JADERN\u00c9 PONORKY\", cost: 400, desc: \"Zisk z\u00e1sob z logistiky ztrojn\u00e1soben.\" };\n            case 'attrition': return { name: \"CHEMICK\u00dd PLYN\", cost: 450, desc: \"Tlak nep\u0159\u00edtele je trvale sn\u00ed\u017een o \u00factyhodn\u00fdch -40%.\" };\n            case 'cyber_rebel': return { name: \"KYBER-\u0160T\u00cdT\", cost: 400, desc: \"Tlak nep\u0159\u00e1telsk\u00e9ho povst\u00e1n\u00ed sn\u00ed\u017een o -20%.\" };\n            case 'nuke_winter': return { name: \"PROTIMRAZOV\u00c1 NAFTA\", cost: 400, desc: \"Zbran\u011b funguj\u00ed skv\u011ble (+30% po\u0161kozen\u00ed).\" };\n            case 'alien_inv': return { name: \"IONTOV\u00dd KAN\u00d3N\", cost: 500, desc: \"Bar\u00e1\u017e okam\u017eit\u011b zni\u010d\u00ed mimozemsk\u00fd energetick\u00fd \u0161t\u00edt.\" };\n            case 'napoleon_siege': return { name: \"D\u011aLOST\u0158ELECK\u00c1 PALBA\", cost: 400, desc: \"Zvy\u0161uje ve\u0161ker\u00e9 po\u0161kozen\u00ed ofenz\u00edvy o +30%.\" };\n            case 'korea': return { name: \"LETECTVO OSN\", cost: 400, desc: \"Leteck\u00fd shoz nese o +50% v\u00edce z\u00e1sob.\" };\n            case 'yom_kippur': return { name: \"OKAM\u017dIT\u00c1 MOBILIZACE\", cost: 400, desc: \"Zm\u00edrn\u00ed \u0161ok z prvn\u00edch 3 dn\u00ed \u00fatoku o polovinu.\" };\n            case 'falklands': return { name: \"SEA HARRIER PODPORA\", cost: 450, desc: \"Ofenz\u00edva stoj\u00ed u\u017e jen 1 Z\u00e1sobu (m\u00edsto 2).\" };\n            case 'mars_colony': return { name: \"TERRAFORMOVAC\u00cd JEDNOTKA\", cost: 450, desc: \"Zisk z\u00e1sob zv\u00fd\u0161en o +40% (kompenzuje nedostatek zdroj\u016f).\" };\n        }\n    }\n\n    function getExclusive2() {\n        switch(state.scenario) {\n            case 'default': return { name: \"ELITN\u00cd D\u016eSTOJN\u00cdCI\", cost: 350, desc: \"Zvy\u0161uje zisk Velitelsk\u00fdch Bod\u016f o +20%.\" };\n            case 'ww1_west': return { name: \"T\u011a\u017dK\u00c9 KULOMETY\", cost: 400, desc: \"Z\u00e1kladn\u00ed denn\u00ed tlak nep\u0159\u00edtele sn\u00ed\u017een o -15%.\" };\n            case 'ww1_east': return { name: \"KO\u0147SK\u00c1 SP\u0158E\u017dEN\u00cd\", cost: 350, desc: \"V\u00fdnos logistiky zv\u00fd\u0161en o +50%.\" };\n            case 'ww2_blitz': return { name: \"LETKA STUKAS\", cost: 400, desc: \"Leteck\u00fd shoz nav\u00edc u\u0161t\u011bd\u0159\u00ed 30 Dmg (FR).\" };\n            case 'ww2_pacific': return { name: \"PLAMENOMETY\", cost: 400, desc: \"Zvy\u0161uje celkov\u00e9 po\u0161kozen\u00ed o +40%.\" };\n            case 'winter_war': return { name: \"LY\u017dA\u0158SK\u00c9 ODD\u00cdLY\", cost: 450, desc: \"Akce Logistiky u\u017e nestoj\u00ed \u017e\u00e1dn\u00e9 body Fronty.\" };\n            case 'vietnam': return { name: \"TUNELOV\u00c9 KRYSY\", cost: 400, desc: \"Kdy\u017e je d\u017eungle odhalena, \u0161ance na Crit je o +20% vy\u0161\u0161\u00ed.\" };\n            case 'modern_ew': return { name: \"SATELITN\u00cd UPLINK\", cost: 450, desc: \"Skill Anti-Ru\u0161i\u010dka stoj\u00ed trvale o -10 VB m\u00e9n\u011b.\" };\n            case 'desert': return { name: \"NO\u010cN\u00cd VID\u011aN\u00cd\", cost: 400, desc: \"Trvale roz\u0161i\u0159uje z\u00f3nu radaru o dal\u0161\u00edch +50%.\" };\n            case 'urban': return { name: \"\u017dENIST\u00c9\", cost: 350, desc: \"V\u00fdnos logistiky zv\u00fd\u0161en o +50%.\" };\n            case 'guerilla': return { name: \"I.E.D. S\u00cd\u0164\", cost: 450, desc: \"Pokud na tebe nep\u0159\u00edtel zatla\u010d\u00ed, utrp\u00ed zran\u011bn\u00ed (Vr\u00e1t\u00ed +3 FR).\" };\n            case 'drone': return { name: \"RU\u0160I\u010cKA SIGN\u00c1LU\", cost: 450, desc: \"Z\u00e1kladn\u00ed denn\u00ed tlak nep\u0159\u00edtele je sn\u00ed\u017een o -25%.\" };\n            case 'zombie': return { name: \"UV SV\u011aTLOMETY\", cost: 500, desc: \"\u00darove\u0148 mutace zomb\u00edk\u016f u\u017e nikdy nem\u016f\u017ee p\u0159es\u00e1hnout 3.\" };\n            case 'space': return { name: \"KINETICK\u00c9 \u0160T\u00cdTY\", cost: 450, desc: \"Z\u00e1kladn\u00ed tlak nep\u0159\u00edtele z vesm\u00edru trvale sn\u00ed\u017een o -30%.\" };\n            case 'blockade': return { name: \"PA\u0160ER\u00c1CK\u00c1 S\u00cd\u0164\", cost: 400, desc: \"Ka\u017ed\u00fd z\u00e1sah do nep\u0159\u00edtele ti daruje +2 Z\u00e1soby.\" };\n            case 'attrition': return { name: \"V\u00c1LE\u010cN\u00c1 EKONOMIKA\", cost: 450, desc: \"Zisk Velitelsk\u00fdch Bod\u016f (VB) je zdvojn\u00e1soben (+100%).\" };\n            case 'cyber_rebel': return { name: \"DE\u0160IFROVAC\u00cd KL\u00cd\u010c\", cost: 450, desc: \"Ka\u017ed\u00fd p\u0159esn\u00fd z\u00e1sah m\u00e1 40% \u0161anci znehybnit nep\u0159\u00edtele.\" };\n            case 'nuke_winter': return { name: \"GEOTERM\u00c1LN\u00cd D\u016eM\", cost: 500, desc: \"Z\u00e1soby v zim\u011b ji\u017e neklesaj\u00ed samovoln\u011b o -1 ka\u017ed\u00fd tah.\" };\n            case 'alien_inv': return { name: \"BIOLOGICK\u00dd VIRUS\", cost: 450, desc: \"Tlak mimozem\u0161\u0165an\u016f kles\u00e1 s ka\u017ed\u00fdm nov\u00fdm dnem o -5% (max -50%).\" };\n            case 'napoleon_siege': return { name: \"LEHK\u00c1 P\u011aCHOTA\", cost: 400, desc: \"Kompenzuje nep\u0159esnost mu\u0161ket - roz\u0161\u00ed\u0159\u00ed zam\u011b\u0159ovac\u00ed z\u00f3nu o +40%.\" };\n            case 'korea': return { name: \"ARKTICK\u00c1 V\u00ddSTROJ\", cost: 400, desc: \"Trvale sn\u00ed\u017e\u00ed denn\u00ed tlak nep\u0159\u00edtele o -20%.\" };\n            case 'yom_kippur': return { name: \"OPERACE ABIREJ-LEV\", cost: 450, desc: \"B\u011bhem prvn\u00edch 3 dn\u00ed zvy\u0161uje po\u0161kozen\u00ed o +30%.\" };\n            case 'falklands': return { name: \"EXOCET RAKETY\", cost: 450, desc: \"Kritick\u00e9 z\u00e1sahy ud\u011bluj\u00ed o +30% v\u00edce po\u0161kozen\u00ed.\" };\n            case 'mars_colony': return { name: \"KOLONI\u00c1LN\u00cd MILICE\", cost: 450, desc: \"Zvy\u0161uje ve\u0161ker\u00e9 po\u0161kozen\u00ed o +25%.\" };\n        }\n    }\n\n    function getExclusive3() {\n        switch(state.scenario) {\n            case 'default': return { name: \"TAKTIKA KRYT\u00cd\", cost: 380, desc: \"Sn\u00ed\u017e\u00ed ve\u0161ker\u00e9 po\u0161kozen\u00ed denn\u00edho tlaku o -20%.\" };\n            case 'ww1_west': return { name: \"Z\u00c1KOPN\u00cd MINY\", cost: 450, desc: \"Pokud se nep\u0159\u00edtel p\u0159ibl\u00ed\u017e\u00ed, bar\u00e1\u017e ho zran\u00ed o dal\u0161\u00edch +40 FR.\" };\n            case 'ww1_east': return { name: \"CARSK\u00c9 REZERVY\", cost: 400, desc: \"Z\u00edsk\u00e1\u0161 pasivn\u011b +5 VB ka\u017ed\u00fd den.\" };\n            case 'ww2_blitz': return { name: \"PANC\u00c9\u0158OV\u00dd KL\u00cdN\", cost: 500, desc: \"Zavede t\u011b\u017ek\u00e9 tanky a zv\u00fd\u0161\u00ed po\u0161kozen\u00ed ofenz\u00edvy o +50%.\" };\n            case 'ww2_pacific': return { name: \"P\u00c1SOV\u00c1 VOZIDLA LVT\", cost: 450, desc: \"P\u0159i ka\u017ed\u00e9m dal\u0161\u00edm sektoru za\u010d\u00edn\u00e1\u0161 s +15% HP fronty nav\u00edc.\" };\n            case 'winter_war': return { name: \"SABOT\u00c1\u017dN\u00cd MINY\", cost: 400, desc: \"Sabot\u00e1\u017e nav\u00edc trvale ochrom\u00ed nep\u0159\u00edtele na 3 dny.\" };\n            case 'vietnam': return { name: \"PR\u016eZKUM ZE VZDUCHU\", cost: 420, desc: \"Odhalen\u00ed d\u017eungle ti okam\u017eit\u011b p\u0159inese +3 Z\u00e1soby.\" };\n            case 'modern_ew': return { name: \"\u0160IFROV\u00c1N\u00cd DAT\", cost: 480, desc: \"Tlak nep\u0159\u00edtele b\u011bhem aktivn\u00edho ru\u0161en\u00ed je sn\u00ed\u017een o -40%.\" };\n            case 'desert': return { name: \"SATELITN\u00cd GPS\", cost: 550, desc: \"Radar se v bou\u0159i nikdy nerozkmit\u00e1 nad kritickou rychlost.\" };\n            case 'urban': return { name: \"BARIK\u00c1DY\", cost: 400, desc: \"Zv\u00fd\u0161\u00ed maxim\u00e1ln\u00ed limit fronty v tomto sektoru o +30%.\" };\n            case 'guerilla': return { name: \"VLASTENECK\u00c9 R\u00c1DIO\", cost: 420, desc: \"Zvy\u0161uje zisk Velitelsk\u00fdch Bod\u016f (VB) o +40%.\" };\n            case 'drone': return { name: \"DRON-MATKA\", cost: 500, desc: \"Z\u00edsk\u00e1v\u00e1\u0161 o +30% vy\u0161\u0161\u00ed \u00fa\u010dinek ze v\u0161ech UAV \u00fader\u016f.\" };\n            case 'zombie': return { name: \"S\u00c9ROLOGIE\", cost: 480, desc: \"Hladina mutace m\u00e1 polovi\u010dn\u00ed negativn\u00ed vliv na denn\u00ed tlak.\" };\n            case 'space': return { name: \"SOL\u00c1RN\u00cd KOLEKTOR\", cost: 500, desc: \"Zvy\u0161uje pasivn\u00ed p\u0159\u00edjem VB o +15 za ka\u017edou \u00farove\u0148 pr\u016fzkumu.\" };\n            case 'blockade': return { name: \"DOPROVODN\u00c9 KORVETY\", cost: 450, desc: \"\u00datoky v tomto sc\u00e9n\u00e1\u0159i stoj\u00ed u\u017e jen 2 Z\u00e1soby (m\u00edsto 3).\" };\n            case 'attrition': return { name: \"KONCENTROVAN\u00c1 PALBA\", cost: 500, desc: \"Zvy\u0161uje po\u0161kozen\u00ed o +60%.\" };\n            case 'cyber_rebel': return { name: \"NEURO-PROPOJEN\u00cd\", cost: 450, desc: \"Umo\u017en\u00ed ovl\u00e1dat radar s o 40% \u0161ir\u0161\u00ed z\u00f3nou.\" };\n            case 'nuke_winter': return { name: \"RECYKLACE TEPLA\", cost: 450, desc: \"Logistika spot\u0159ebov\u00e1v\u00e1 o -3 FR m\u00e9n\u011b zdrav\u00ed linie.\" };\n            case 'alien_inv': return { name: \"DESTRUKTOR \u0160T\u00cdT\u016e\", cost: 550, desc: \"\u00datoky kompletn\u011b ignoruj\u00ed mimozemsk\u00fd \u0161t\u00edt a ud\u011bl\u00ed o 30% vy\u0161\u0161\u00ed dmg.\" };\n            case 'napoleon_siege': return { name: \"OPEVN\u011aN\u00cd\", cost: 420, desc: \"Jednor\u00e1zov\u011b nav\u00fd\u0161\u00ed strop fronty pro tento sektor o +25%.\" };\n            case 'korea': return { name: \"MOR\u00c1LN\u00cd PODPORA\", cost: 400, desc: \"Zvy\u0161uje zisk Velitelsk\u00fdch Bod\u016f o +25%.\" };\n            case 'yom_kippur': return { name: \"LETECK\u00dd MOST\", cost: 420, desc: \"Zvy\u0161uje zisk z\u00e1sob o +50%.\" };\n            case 'falklands': return { name: \"V\u00ddSADEK SAN CARLOS\", cost: 420, desc: \"Jednor\u00e1zov\u011b nav\u00fd\u0161\u00ed strop fronty pro tento sektor o +20%.\" };\n            case 'mars_colony': return { name: \"KVANTOV\u00dd PO\u010c\u00cdTA\u010c\", cost: 480, desc: \"Zvy\u0161uje zisk Velitelsk\u00fdch Bod\u016f o +35%.\" };\n            default: return { name: \"Z\u00c1LO\u017dN\u00cd HQ\", cost: 300, desc: \"Okam\u017eit\u011b obdr\u017e\u00ed\u0161 +10 Z\u00e1sob.\" };\n        }\n    }\n\n    function setScenario(scen) { \n        Sound.unlock();\n        Sound.click();\n        state.scenario = scen; \n        el('screen-scenario').classList.remove('active'); \n        el('screen-doctrine').classList.add('active'); \n        tutorialAdvanceIf('scenario');\n    }\n    \n    function setDoctrine(doc) {\n        Sound.click();\n        state.doctrine = doc; \n        el('screen-doctrine').classList.remove('active');\n        \n        let critBase = 15;\n        if (state.doctrine === 'fortress') { \n            el('lbl-doctrine').innerText = \"PEVNOST\"; \n        } \n        else if (state.doctrine === 'blitz') { el('lbl-doctrine').innerText = \"BLITZ\"; } \n        else if (state.doctrine === 'intel') { critBase = 40; el('lbl-doctrine').innerText = \"INTEL\"; }\n        else if (state.doctrine === 'quartermaster') { state.supplies = 20; el('lbl-doctrine').innerText = \"Z\u00c1SOBY\"; }\n        else if (state.doctrine === 'tech') { \n            Object.keys(state.upgrades).forEach(k => state.upgrades[k].cost = Math.floor(state.upgrades[k].cost * 0.75)); \n            el('lbl-doctrine').innerText = \"TECH\"; \n        }\n        else if (state.doctrine === 'artillery') { \n            state.costArt = Math.floor(state.costArt * 0.75); \n            state.costAir = Math.floor(state.costAir * 0.75); \n            critBase = 5; \n            el('lbl-doctrine').innerText = \"SHOCK\"; \n        }\n        else if (state.doctrine === 'partisan') { el('lbl-doctrine').innerText = \"ODBOJ\"; }\n        else if (state.doctrine === 'propaganda') { el('lbl-doctrine').innerText = \"OSV\u011aTA\"; }\n        else if (state.doctrine === 'fanatic') { \n            Object.keys(state.upgrades).forEach(k => state.upgrades[k].cost = Math.floor(state.upgrades[k].cost * 1.3)); \n            el('lbl-doctrine').innerText = \"V\u00cdRA\"; \n        }\n        else if (state.doctrine === 'fleet') { el('lbl-doctrine').innerText = \"FLEET\"; }\n        else if (state.doctrine === 'mercenary') { el('lbl-doctrine').innerText = \"\u017dOLD\u00c1CI\"; }\n        else if (state.doctrine === 'chemical') { el('lbl-doctrine').innerText = \"TOXIC\"; }\n\n        // V\u00fdpo\u010det po\u010d\u00e1te\u010dn\u00edho maxFront na z\u00e1klad\u011b sc\u00e9n\u00e1\u0159e\n        let baseMax = getScenarioBaseMaxFront(state.scenario);\n        state.maxFront = baseMax;\n        \n        // Zohledn\u011bn\u00ed \u017denist\u016f pro po\u010d\u00e1te\u010dn\u00ed zdrav\u00ed\n        let engBonus = 1 + ((state.upgrades.engineering.level - 1) * 0.05);\n        state.front = Math.floor(state.maxFront * 0.5 * engBonus);\n\n        const scMap = { \n            'default': 'Z\u00c1KLAD', 'napoleon_siege': 'OBL\u00c9H\u00c1N\u00cd', 'ww1_west': 'Z\u00c1KOPY', 'ww1_east': 'V\u00ddCHOD', 'ww2_blitz': 'BLITZ', \n            'ww2_pacific': 'PACIFIK', 'winter_war': 'ZIMA', 'korea': 'KOREA', 'vietnam': 'VIETNAM', 'yom_kippur': 'JOM KIPUR', \n            'falklands': 'FALKLANDY', 'modern_ew': 'KYBER', \n            'desert': 'POU\u0160\u0164', 'urban': 'M\u011aSTO', 'guerilla': 'ODBOJ', 'drone': 'DRONY', \n            'zombie': 'N\u00c1KAZA', 'space': 'VESM\u00cdR', 'blockade': 'BLOK\u00c1DA', 'attrition': 'ML\u00ddNEK',\n            'cyber_rebel': 'POVST\u00c1N\u00cd', 'nuke_winter': 'NUKE_ZIMA', 'alien_inv': 'INVAZE', 'mars_colony': 'MARS'\n        };\n        el('lbl-scenario').innerText = scMap[state.scenario] || state.scenario.toUpperCase();\n\n        if (state.scenario === 'ww2_pacific') { \n            state.maxFront = Math.floor(200 * engBonus); \n            state.front = Math.floor(100 * engBonus); \n            el('btn-sup').innerHTML = \"RYBOLOV<br><small>Tlak</small>\"; \n        }\n        else if (state.scenario === 'winter_war') { state.baseEnemyPush += 4; }\n        else if (state.scenario === 'desert') { state.baseEnemyPush = 10; }\n        else if (state.scenario === 'urban') { \n            state.maxFront = Math.floor(1000 * engBonus); \n            state.front = Math.floor(500 * engBonus); \n            state.baseEnemyPush = 4; \n        }\n        else if (state.scenario === 'guerilla') { state.supplies = 5; el('btn-sup').innerHTML = \"PA\u0160OV\u00c1N\u00cd<br><small>Tlak</small>\"; }\n        else if (state.scenario === 'zombie') { state.baseEnemyPush = 4; }\n        else if (state.scenario === 'space') { state.baseEnemyPush = 12; }\n        else if (state.scenario === 'blockade') { state.supplies = 15; }\n        else if (state.scenario === 'attrition') { state.baseEnemyPush = 8; el('btn-atk').innerHTML = \"MASOV\u00dd \u00daTOK<br><small>-1 Z</small>\"; }\n        else if (state.scenario === 'nuke_winter') { state.baseEnemyPush = 8; }\n        else if (state.scenario === 'alien_inv') { state.alienShield = 150; }\n        else if (state.scenario === 'korea') { state.baseEnemyPush = 10; }\n        else if (state.scenario === 'falklands') { state.supplies = 12; }\n\n        // Bonus doktr\u00edny Pevnost (+20% Max Fronta) a p\u0159\u00edpadn\u00e1 synergie - aplikuje se na FIN\u00c1LN\u00cd hodnotu,\n        // a\u017e po v\u0161ech sc\u00e9n\u00e1\u0159ov\u011b specifick\u00fdch \u00faprav\u00e1ch v\u00fd\u0161e (aby se \u017e\u00e1dnou z nich nep\u0159epsal).\n        let frontMultiplier = 1.0;\n        if (state.doctrine === 'fortress') frontMultiplier *= 1.20;\n        frontMultiplier *= (1 + getSynergyBonus('maxFrontOnce'));\n        if (frontMultiplier !== 1.0) {\n            state.maxFront = Math.floor(state.maxFront * frontMultiplier);\n            state.front = Math.floor(state.front * frontMultiplier);\n        }\n\n        el('val-crit').innerText = `${critBase}%`;\n        el('game-screen').style.display = 'block';\n        \n        logMessage(\"SYST\u00c9M FRONTLINES v4.0 AKTIVOV\u00c1N. P\u0159ejeme \u00fasp\u011b\u0161n\u00fd lov.\", \"t-white\"); \n\n        let syn = getSynergy();\n        if (syn && !tutorialActive) {\n            setTimeout(() => showUnlockNotification(`\u2b50 SYNERGIE AKTIVN\u00cd:<br>${syn.label}`), 800);\n        }\n\n        updateUI();\n        tutorialAdvanceIf('doctrine');\n    }\n\n    function logMessage(msg, col = \"t-white\") {\n        const lb = el('log');\n        if (!lb) return;\n        const entry = document.createElement('div'); \n        entry.className = `log-entry ${col}`; \n        entry.innerHTML = `> ${msg}`;\n        lb.appendChild(entry); \n        lb.scrollTop = lb.scrollHeight;\n    }\n\n    function getEnemyPush() {\n        if (state.godMode) return 0;\n        if (state.enemyStunned > 0) return 0;\n        let base = state.baseEnemyPush + Math.floor(state.day / 4) + ((state.sector - 1) * 3);\n        \n        let pctMod = 1.0; \n\n        // V\u00fdzkum panc\u00ed\u0159e\n        pctMod -= ((state.upgrades.armor.level - 1) * 0.05); \n\n        // Vliv doktr\u00edn a exkluzivn\u00edch modul\u016f\n        if (state.doctrine === 'fortress') pctMod -= 0.20;\n        if (state.doctrine === 'blitz') pctMod += 0.15;\n        if (state.doctrine === 'propaganda') pctMod += 0.15;\n\n        if (state.scenario === 'default' && state.exclusiveBought1) pctMod -= 0.15;\n        if (state.scenario === 'ww1_west' && state.exclusiveBought2) pctMod -= 0.15;\n        if (state.scenario === 'drone' && state.exclusiveBought2) pctMod -= 0.25;\n        if (state.scenario === 'space' && state.exclusiveBought2) pctMod -= 0.30;\n        if (state.scenario === 'attrition' && state.exclusiveBought1) pctMod -= 0.40;\n        if (state.scenario === 'cyber_rebel' && state.exclusiveBought1) pctMod -= 0.20;\n        if (state.scenario === 'default' && state.exclusiveBought3) pctMod -= 0.20; \n        if (state.scenario === 'modern_ew' && state.exclusiveBought3 && state.modern_counterTimer <= 0) pctMod -= 0.40;\n        if (state.scenario === 'alien_inv' && state.exclusiveBought2) pctMod -= Math.min(0.50, (state.day - 1) * 0.05);\n\n        if (state.scenario === 'ww2_blitz' && state.ww2_momentumEnemy > 0) pctMod += (state.ww2_momentumEnemy * 0.4);\n        if (state.scenario === 'nuke_winter') pctMod *= 0.5; // Zpomalen\u00ed v zim\u011b\n        if (state.scenario === 'yom_kippur' && state.day <= 3) {\n            pctMod *= state.exclusiveBought1 ? 1.5 : 2.0; // \u0160ok z n\u00e1hl\u00e9ho \u00fatoku, mobilizace ho zm\u00edrn\u00ed\n        }\n        pctMod += getSynergyBonus('push');\n\n        pctMod = Math.max(0.1, pctMod); \n        let finalPush = Math.floor(base * pctMod);\n\n        if (state.scenario === 'zombie') {\n            let mVal = state.zombie_mutation;\n            if (state.exclusiveBought2 && mVal > 3) mVal = 3;\n            if (state.exclusiveBought3) mVal = Math.floor(mVal * 0.5);\n            finalPush += mVal;\n        }\n        \n        return Math.max(0, finalPush);\n    }\n\n    function updateScenarioModule() {\n        let t = el('scenario-status'), d = el('scenario-desc'), m = el('scenario-module');\n        m.style.borderColor = \"var(--border)\";\n\n        if (state.scenario === 'default') { t.innerText = \"Z\u00c1KLADN\u00cd FRONTA\"; t.className = \"t-white\"; d.innerText = \"Standardn\u00ed operace.\"; } \n        else if (state.scenario === 'ww1_west') { t.innerText = `P\u0158\u00cdPRAVA NA ZTE\u010c: ${state.ww1_trenchPrep} BOD\u016e`; t.className = \"t-orange\"; d.innerText = \"Zte\u010d spust\u00edte stisknut\u00edm dedikovan\u00e9ho tla\u010d\u00edtka SKILL.\"; m.style.borderColor = \"var(--warning)\"; } \n        else if (state.scenario === 'ww1_east') { t.innerText = \"HLADOMOR\"; t.className = \"t-red\"; d.innerText = \"Logistika m\u00e1 zmen\u0161enou efektivitu.\"; } \n        else if (state.scenario === 'ww2_blitz') {\n            if (state.ww2_momentumEnemy > 0) { t.innerText = `NEP\u0158\u00c1TELSK\u00c1 HYBNOST (+${state.ww2_momentumEnemy})`; t.className = \"t-red\"; d.innerText = \"Tlak nep\u0159\u00edtele roste!\"; }\n            else { t.innerText = `TVOJE HYBNOST (+${state.ww2_momentumPlayer})`; t.className = \"t-green\"; d.innerText = \"Bleskov\u00fd postup vp\u0159ed!\"; }\n        } \n        else if (state.scenario === 'ww2_pacific') { t.innerText = `OSTROVN\u00cd KAMPA\u0147 (Sektor ${state.sector})`; t.className = \"t-blue\"; d.innerText = \"Ustupov\u00e1n\u00ed nemo\u017en\u00e9.\"; m.style.borderColor = \"var(--tech)\"; } \n        else if (state.scenario === 'winter_war') { t.innerText = \"ZAMRZL\u00c9 PEKLO\"; t.className = \"t-white\"; d.innerText = \"Masivn\u00ed tlak nep\u0159\u00e1telsk\u00e9 p\u0159esily.\"; } \n        else if (state.scenario === 'vietnam') {\n            if (state.viet_revealed > 0) { t.innerText = `D\u017dUNGLE ODHALENA (${state.viet_revealed} dny)`; t.className = \"t-orange\"; d.innerText = \"Nep\u0159\u00edtel lokalizov\u00e1n.\"; }\n            else { t.innerText = \"NEVIDITELN\u00c1 FRONTA\"; t.className = \"t-red\"; d.innerText = \"Frontov\u00e9 linie jsou kompletn\u011b skryt\u00e9 v d\u017eungli.\"; }\n        } \n        else if (state.scenario === 'modern_ew') {\n            if (state.modern_counterTimer > 0) { t.innerText = `ANTI-RU\u0160I\u010cKA AKTIVN\u00cd (${state.modern_counterTimer} d.)`; t.className = \"t-green\"; }\n            else { t.innerText = \"ELEKTRONICK\u00c9 RU\u0160EN\u00cd\"; t.className = \"t-purple\"; d.innerText = \"Radar se pohybuje extr\u00e9mn\u011b nestabiln\u011b.\"; m.style.borderColor = \"var(--purple)\"; }\n        }\n        else if (state.scenario === 'desert') { t.innerText = \"POU\u0160TN\u00cd BOU\u0158E\"; t.className = \"t-orange\"; d.innerText = \"Z\u00e1sobov\u00e1n\u00ed zt\u00ed\u017eeno. Ofenz\u00edva vy\u017eaduje 2 Z\u00e1soby.\"; }\n        else if (state.scenario === 'urban') { t.innerText = \"M\u011aSTSK\u00dd BOJ\"; t.className = \"t-red\"; d.innerText = \"Boj v ruin\u00e1ch sni\u017euje tv\u00e9 z\u00e1kladn\u00ed po\u0161kozen\u00ed o 50%.\"; }\n        else if (state.scenario === 'guerilla') { t.innerText = \"ASYMETRICK\u00dd BOJ\"; t.className = \"t-green\"; d.innerText = \"Z\u00e1soby krade\u0161 p\u0159\u00edmo p\u0159esn\u00fdmi z\u00e1sahy.\"; }\n        else if (state.scenario === 'drone') { t.innerText = \"BEZPILOTN\u00cd V\u00c1LKA\"; t.className = \"t-blue\"; d.innerText = \"Konven\u010dn\u00ed letectvo a d\u011blost\u0159electvo mimo provoz.\"; }\n        else if (state.scenario === 'zombie') { t.innerText = `\u00daROVE\u0147 MUTACE: ${state.zombie_mutation}`; t.className = \"t-toxic\"; d.innerText = \"Minut\u00ed vyvol\u00e1 mutaci. Ka\u017ed\u00e1 \u00farove\u0148 zvy\u0161uje trval\u00fd tlak!\"; m.style.borderColor = \"var(--toxic)\"; }\n        else if (state.scenario === 'space') { t.innerText = \"ORBIT\u00c1LN\u00cd RYCHLOST\"; t.className = \"t-cyan\"; d.innerText = \"Frekvence radaru je smrt\u00edc\u00ed.\"; m.style.borderColor = \"var(--cyan)\"; }\n        else if (state.scenario === 'blockade') { t.innerText = \"N\u00c1MO\u0158N\u00cd BLOK\u00c1DA\"; t.className = \"t-blue\"; d.innerText = \"Pr\u016flom linie stoj\u00ed enormn\u00ed zdroje (3 Z\u00e1soby).\"; }\n        else if (state.scenario === 'attrition') { t.innerText = \"ML\u00ddNEK NA MASO\"; t.className = \"t-red\"; d.innerText = \"Radar zni\u010den. Spol\u00e9h\u00e1te se na matematickou p\u0159evahu.\"; }\n        \n        // Nov\u00e9 moduly\n        else if (state.scenario === 'cyber_rebel') { t.innerText = \"KYBERNETICK\u00c1 REBELIE\"; t.className = \"t-cyan\"; d.innerText = \"Radar je ru\u0161en, ale ka\u017ed\u00fd \u00fasp\u011b\u0161n\u00fd z\u00e1sah d\u00e1v\u00e1 +20 VB.\"; m.style.borderColor = \"var(--cyan)\"; }\n        else if (state.scenario === 'nuke_winter') { t.innerText = \"NUKLE\u00c1RN\u00cd ZIMA\"; t.className = \"t-blue\"; d.innerText = \"Z\u00e1soby klesaj\u00ed o 1 za tah. Nep\u0159\u00edtel je v\u0161ak pomalej\u0161\u00ed.\"; m.style.borderColor = \"var(--tech)\"; }\n        else if (state.scenario === 'alien_inv') { t.innerText = `MIMOZEMSK\u00dd \u0160T\u00cdT: ${state.alienShield} HP`; t.className = \"t-cyan\"; d.innerText = \"Absorbuje ve\u0161ker\u00e9 po\u0161kozen\u00ed. Dob\u00edj\u00ed se ka\u017ed\u00fdch 5 dn\u00ed.\"; m.style.borderColor = \"var(--cyan)\"; }\n        \n        // Moduly nov\u00fdch sc\u00e9n\u00e1\u0159\u016f\n        else if (state.scenario === 'napoleon_siege') { t.innerText = \"NEP\u0158ESN\u00c9 MU\u0160KETY\"; t.className = \"t-orange\"; d.innerText = \"\u00dazk\u00e1 zam\u011b\u0159ovac\u00ed z\u00f3na, ale \u00fatoky jsou levn\u00e9 a \u010dast\u00e9.\"; }\n        else if (state.scenario === 'korea') { t.innerText = \"LIDSK\u00c9 VLNY ZE SEVERU\"; t.className = \"t-red\"; d.innerText = \"Drtiv\u00fd tlak p\u0159esily. Leteck\u00e9 shozy OSN jsou kl\u00ed\u010dov\u00e9.\"; }\n        else if (state.scenario === 'yom_kippur') {\n            if (state.day <= 3) { t.innerText = `N\u00c1HL\u00dd \u00daTOK (den ${state.day}/3)`; t.className = \"t-red\"; d.innerText = \"\u0160ok z p\u0159ekvapiv\u00e9ho \u00fatoku - tlak nep\u0159\u00edtele je do\u010dasn\u011b dvojn\u00e1sobn\u00fd.\"; m.style.borderColor = \"var(--danger)\"; }\n            else { t.innerText = \"PROTI\u00daTOK V PLN\u00c9M PROUDU\"; t.className = \"t-green\"; d.innerText = \"Po\u010d\u00e1te\u010dn\u00ed \u0161ok pominul. Linie se stabilizovala.\"; }\n        }\n        else if (state.scenario === 'falklands') { t.innerText = \"Z\u00c1SOBOV\u00c1N\u00cd P\u0158ES OCE\u00c1N\"; t.className = \"t-blue\"; d.innerText = \"Ofenz\u00edva stoj\u00ed 2 Z\u00e1soby, ale p\u0159esnost zbran\u00ed d\u00e1v\u00e1 +10% \u0161anci na kritick\u00fd z\u00e1sah.\"; }\n        else if (state.scenario === 'mars_colony') { t.innerText = \"N\u00cdZK\u00c1 GRAVITACE\"; t.className = \"t-red\"; d.innerText = \"V\u00fdbu\u0161niny jsou siln\u011bj\u0161\u00ed (+10% Dmg), ale zdroj\u016f je nedostatek (-20% Z\u00e1sob).\"; m.style.borderColor = \"var(--danger)\"; }\n\n        let syn = getSynergy();\n        if (syn) {\n            d.innerText += ` \u2b50 Synergie \u201e${syn.label}\" je aktivn\u00ed.`;\n            m.style.borderColor = \"var(--gold, #fbbf24)\";\n        }\n    }\n\n    function updateUI() {\n        if (state.gamePaused) return;\n\n        let p = (state.front / state.maxFront) * 100;\n        let displayedFront = Math.max(0, Math.min(state.front, state.maxFront)); \n        \n        let g = el('gauge'); \n        g.style.width = `${Math.max(0, Math.min(100, p))}%`;\n        let cont = el('gauge-container');\n        \n        if (state.scenario === 'vietnam' && state.viet_revealed <= 0) { \n            cont.classList.add('vietnam-hidden'); \n            el('gauge-text').innerText = \"FRONTLINE: ??? / ???\"; \n        } \n        else {\n            cont.classList.remove('vietnam-hidden'); \n            el('gauge-text').innerHTML = `FRONTLINE: <span id=\"val-front\">${displayedFront}</span> / ${state.maxFront}`;\n            if (p < 25) { \n                el('game-screen').classList.add('crisis'); \n                g.style.backgroundColor = 'var(--danger)'; \n            }\n            else { \n                el('game-screen').classList.remove('crisis'); \n                g.style.backgroundColor = p < 60 ? 'var(--warning)' : 'var(--accent)'; \n            }\n        }\n\n        el('val-day').innerText = state.day; \n        el('val-sup').innerText = state.supplies; \n        el('val-cp').innerText = state.cp;\n        el('val-push').innerText = `-${getEnemyPush()}`;\n\n        // V\u00fdpo\u010det ceny \u00fatoku\n        let atkCost = 1;\n        if (state.scenario === 'desert' && !state.exclusiveBought1) atkCost = 2;\n        if (state.scenario === 'blockade' && !state.exclusiveBought3) atkCost = 3;\n        if (state.scenario === 'blockade' && state.exclusiveBought3) atkCost = 2;\n        if (state.scenario === 'falklands' && !state.exclusiveBought1) atkCost = 2;\n        \n        if (state.scenario !== 'attrition') el('btn-atk').innerHTML = `OFENZ\u00cdVA<br><small>-${atkCost} Z</small>`;\n        el('btn-atk').disabled = state.supplies < atkCost;\n\n        el('btn-art').innerHTML = `Bar\u00e1\u017e<br><small>${state.costArt} VB</small>`;\n        el('btn-air').innerHTML = `Shoz<br><small>${state.costAir} VB</small>`;\n        \n        if (state.scenario === 'drone') { \n            el('btn-art').disabled = true; \n            el('btn-air').disabled = true; \n        } else {\n            el('btn-art').disabled = state.cp < state.costArt;\n            el('btn-air').disabled = state.cp < state.costAir;\n        }\n\n        // V\u00fdpo\u010det dovednost\u00ed sc\u00e9n\u00e1\u0159e\n        let sBtn = el('btn-scenario');\n        let skCost = state.doctrine === 'artillery' ? 0.75 : 1;\n        skCost *= (1 + getSynergyBonus('skillCost'));\n        \n        if (state.scenario === 'default') { sBtn.innerHTML = \"Uzam\u010deno<br><small>---</small>\"; sBtn.disabled = true; }\n        else if (state.scenario === 'ww1_west') { sBtn.innerHTML = \"Na Zte\u010d!<br><small>Akce</small>\"; sBtn.disabled = state.ww1_trenchPrep === 0; }\n        else if (state.scenario === 'ww1_east') { sBtn.innerHTML = `Rekv\u00edrovat<br><small>-${state.exclusiveBought1 ? 5 : 15} FR</small>`; sBtn.disabled = state.front <= (state.exclusiveBought1 ? 5 : 15); }\n        else if (state.scenario === 'ww2_blitz') { let c = Math.floor(40*skCost); sBtn.innerHTML = `Pr\u016flom<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'ww2_pacific') { let c = Math.floor(20*skCost); sBtn.innerHTML = `Konvoj<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'winter_war') { let c = Math.floor(20*skCost); sBtn.innerHTML = `Sabot\u00e1\u017e<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'vietnam') { let c = Math.floor(30*skCost); sBtn.innerHTML = `Napalm<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'modern_ew') { \n            let c = Math.floor(25*skCost); \n            if (state.exclusiveBought2) c = Math.max(0, c - 10);\n            sBtn.innerHTML = `Anti-Ru\u0161i\u010d<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c || state.modern_counterTimer > 0; \n        }\n        else if (state.scenario === 'desert') { let c = Math.floor(50*skCost); sBtn.innerHTML = `N\u00e1let<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'urban') { let c = Math.floor(15*skCost); sBtn.innerHTML = `Sniper<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'guerilla') { let c = Math.floor(20*skCost); sBtn.innerHTML = `P\u0159epad<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'drone') { let c = Math.floor(25*skCost); sBtn.innerHTML = `UAV \u00dader<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'zombie') { let c = Math.floor(30*skCost); sBtn.innerHTML = `O\u010dista<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c || state.zombie_mutation === 0; }\n        else if (state.scenario === 'space') { let c = Math.floor(60*skCost); sBtn.innerHTML = `Orb. Laser<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'blockade') { let c = Math.floor(40*skCost); sBtn.innerHTML = `Prolomit<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'attrition') { let c = Math.floor(35*skCost); sBtn.innerHTML = `Vlna<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        \n        // Nov\u00e9 dovednosti pro sc\u00e9n\u00e1\u0159e\n        else if (state.scenario === 'cyber_rebel') { let c = Math.floor(25*skCost); sBtn.innerHTML = `Overload<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'nuke_winter') { let c = Math.floor(30*skCost); sBtn.innerHTML = `Blizard<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'alien_inv') { let c = Math.floor(35*skCost); sBtn.innerHTML = `EMP V\u00fdboj<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c || state.alienShield <= 0; }\n        else if (state.scenario === 'napoleon_siege') { let c = Math.floor(30*skCost); sBtn.innerHTML = `D\u011blost\u0159elba<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'korea') { let c = Math.floor(40*skCost); sBtn.innerHTML = `Bombardov\u00e1n\u00ed<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'yom_kippur') { let c = Math.floor(35*skCost); sBtn.innerHTML = `Proti\u00fatok<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'falklands') { let c = Math.floor(35*skCost); sBtn.innerHTML = `Bombardov\u00e1n\u00ed<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n        else if (state.scenario === 'mars_colony') { let c = Math.floor(55*skCost); sBtn.innerHTML = `Orb. \u00dader<br><small>${c} VB</small>`; state.costSkill = c; sBtn.disabled = state.cp < c; }\n\n        // Nastaven\u00ed radaru\n        let z = el('t-zone'); \n        let realRadVal = getRadarWidth();\n        z.style.width = `${realRadVal}%`; \n        z.style.left = `${50 - (realRadVal / 2)}%`;\n        \n        // Aktualizace popisk\u016f a cen u v\u0161ech 9 glob\u00e1ln\u00edch upgrad\u016f\n        Object.keys(upgradeUIMap).forEach(k => { \n            let s = upgradeUIMap[k]; \n            el(`cost-${s}`).innerText = state.upgrades[k].cost; \n            el(`upg-${s}`).disabled = state.cp < state.upgrades[k].cost; \n            \n            let lvl = state.upgrades[k].level;\n            if (k === 'supply') el(`info-${s}`).innerText = `V\u00fdnos +${Math.round((lvl-1)*30)}% (Lv.${lvl})`;\n            if (k === 'radar') el(`info-${s}`).innerText = `Z\u00f3na +${Math.round((lvl-1)*25)}% (Lv.${lvl})`;\n            if (k === 'dmg') el(`info-${s}`).innerText = `S\u00edla +${Math.round((lvl-1)*20)}% (Lv.${lvl})`;\n            if (k === 'cpGain') el(`info-${s}`).innerText = `P\u0159\u00edjem +${Math.round((lvl-1)*20)}% (Lv.${lvl})`;\n            if (k === 'armor') el(`info-${s}`).innerText = `Tlak -${Math.round((lvl-1)*5)}% (Lv.${lvl})`;\n            if (k === 'recon') el(`info-${s}`).innerText = `Pasiv +${lvl > 1 ? Math.floor(15 * (1 + (lvl - 2) * 0.70)) : 0} VB (Lv.${lvl})`;\n            if (k === 'critical') el(`info-${s}`).innerText = `\u0160ance +${Math.round((lvl-1)*5)}% (Lv.${lvl})`;\n            if (k === 'intel_gain') el(`info-${s}`).innerText = `Z\u00f3na +${Math.round((lvl-1)*3)}, Z\u00e1chrana +${Math.round((lvl-1)*10)}% (Lv.${lvl})`;\n            if (k === 'engineering') el(`info-${s}`).innerText = `Start HP +${Math.round((lvl-1)*5)}% (Lv.${lvl})`;\n        });\n\n        // Tla\u010d\u00edtka exkluzivn\u00edch technologi\u00ed\n        let ex1 = getExclusive1(), btnEx1 = el('btn-excl-1');\n        if (state.exclusiveBought1) { btnEx1.innerHTML = `\u2605 ${ex1.name} \u2605<br><small>AKTIVN\u00cd</small>`; btnEx1.disabled = true; } \n        else { btnEx1.innerHTML = `\u2605 ${ex1.name} \u2605<br><small style=\"font-weight:normal;\">${ex1.cost} VB - ${ex1.desc}</small>`; btnEx1.disabled = state.cp < ex1.cost; }\n\n        let ex2 = getExclusive2(), btnEx2 = el('btn-excl-2');\n        if (state.exclusiveBought2) { btnEx2.innerHTML = `\u2605 ${ex2.name} \u2605<br><small>AKTIVN\u00cd</small>`; btnEx2.disabled = true; } \n        else { btnEx2.innerHTML = `\u2605 ${ex2.name} \u2605<br><small style=\"font-weight:normal;\">${ex2.cost} VB - ${ex2.desc}</small>`; btnEx2.disabled = state.cp < ex2.cost; }\n\n        let ex3 = getExclusive3(), btnEx3 = el('btn-excl-3');\n        if (state.exclusiveBought3) { btnEx3.innerHTML = `\u2605 ${ex3.name} \u2605<br><small>AKTIVN\u00cd</small>`; btnEx3.disabled = true; } \n        else { btnEx3.innerHTML = `\u2605 ${ex3.name} \u2605<br><small style=\"font-weight:normal;\">${ex3.cost} VB - ${ex3.desc}</small>`; btnEx3.disabled = state.cp < ex3.cost; }\n\n        updateScenarioModule(); \n        checkWinLoss(); \n    }\n\n    function triggerShake() { \n        let s = el('game-screen'); \n        s.classList.add('shake'); \n        setTimeout(() => s.classList.remove('shake'), 300); \n    }\n    \n    function applyInstantAction(msg, color, snap, soundName) {\n        if (snap) floatDiffs(snap);\n        if (soundName && Sound[soundName]) Sound[soundName]();\n        logMessage(msg, color); \n        updateUI(); \n    }\n\n    // Spo\u010d\u00edt\u00e1 rozd\u00edl oproti \"snap\" (stav p\u0159ed akc\u00ed) a vykresl\u00ed l\u00e9taj\u00edc\u00ed \u010d\u00edsla\n    function floatDiffs(snap) {\n        let df = state.front - snap.f, ds = state.supplies - snap.s, dc = state.cp - snap.c;\n        if (df !== 0) floatText(`${df > 0 ? '+' : ''}${df} FR`, df > 0 ? 't-green' : 't-red');\n        if (ds !== 0) floatText(`${ds > 0 ? '+' : ''}${ds} Z`, 't-orange');\n        if (dc !== 0) floatText(`${dc > 0 ? '+' : ''}${dc} VB`, dc > 0 ? 't-blue' : 't-red');\n    }\n\n    function endTurn(msg, color) {\n        if (msg) logMessage(msg, color);\n        \n        let snap = { f: state.front, s: state.supplies, c: state.cp };\n\n        let passCp = getPassiveCp();\n        if (passCp > 0) { \n            state.cp += passCp; \n            logMessage(`Pr\u016fzkumn\u00e1 s\u00ed\u0165 vygenerovala +${passCp} VB.`, \"t-blue\"); \n        }\n\n        if (state.doctrine === 'propaganda') {\n            if (state.day % 10 === 0) { \n                state.front += 50; \n                logMessage(\"OSV\u011aTA: Nov\u00e9 posily dorazily na frontu (+50 FR)!\", \"t-cyan\"); \n            }\n        }\n        if (state.doctrine === 'mercenary') {\n            let mercCp = state.supplies * 2;\n            state.cp += mercCp;\n            logMessage(`\u017dOLD\u00c1CI: Kontrakt vyplatil +${mercCp} VB za zbyl\u00e9 z\u00e1soby.`, \"t-gold\");\n        }\n        if (state.doctrine === 'partisan' && state.enemyStunned === 0 && Math.random() < 0.25) {\n            state.enemyStunned = 1; \n            logMessage(\"Partyz\u00e1nsk\u00fd odboj \u00fasp\u011b\u0161n\u011b napadl z\u00e1sobov\u00e1n\u00ed nep\u0159\u00edtele! (Ochromen)\", \"t-toxic\");\n        }\n        if (state.scenario === 'ww1_east' && state.exclusiveBought3) {\n            state.cp += 5;\n            logMessage(\"CARSK\u00c9 REZERVY: Posledn\u00ed z\u00e1lohy carsk\u00e9 pokladny vyplatily +5 VB.\", \"t-gold\");\n        }\n\n        // Tlak nep\u0159\u00edtele\n        let push = getEnemyPush();\n        let tookDamage = false;\n        if (state.enemyStunned > 0) { \n            logMessage(`--- DEN ${state.day} (Nep\u0159\u00edtel ochromen, zb\u00fdv\u00e1 ${state.enemyStunned} d.) ---`, \"t-blue\"); \n            state.enemyStunned--; \n        } else if (push > 0) { \n            logMessage(`--- DEN ${state.day} (Tlak nep\u0159\u00edtele: -${push}) ---`, \"t-red\"); \n            state.front -= push; \n            tookDamage = true;\n            if (state.scenario === 'guerilla' && state.exclusiveBought2) { \n                state.front += 3; \n                logMessage(\"I.E.D. S\u00cd\u0164 zranila \u00fato\u010dn\u00edky v z\u00e1zem\u00ed (+3 FR)\", \"t-orange\"); \n            }\n            if (state.scenario === 'ww1_west' && state.exclusiveBought3) {\n                state.front += 40;\n                logMessage(\"Z\u00c1KOPN\u00cd MINY explodovaly pod postupuj\u00edc\u00edm nep\u0159\u00edtelem (+40 FR)!\", \"t-orange\");\n            }\n        }\n\n        // Nukle\u00e1rn\u00ed zima: samovoln\u00fd pokles z\u00e1sob\n        if (state.scenario === 'nuke_winter' && !state.exclusiveBought2) {\n            state.supplies = Math.max(0, state.supplies - 1);\n            logMessage(\"NUKLE\u00c1RN\u00cd ZIMA: Krut\u00fd mr\u00e1z spot\u0159eboval -1 Z\u00e1sobu.\", \"t-red\");\n        }\n\n        // Mimozemsk\u00e1 regenerace \u0161t\u00edtu\n        if (state.scenario === 'alien_inv' && state.day % 5 === 0) {\n            state.alienShield += 100;\n            logMessage(\"MIMOZEMSK\u00c1 INVAZE: Energetick\u00e9 \u0161t\u00edty nep\u0159\u00edtele se dobily (+100 HP)!\", \"t-cyan\");\n        }\n\n        if (state.scenario === 'vietnam' && state.viet_revealed > 0) state.viet_revealed--;\n        if (state.scenario === 'modern_ew' && state.modern_counterTimer > 0) state.modern_counterTimer--;\n        \n        state.day++; \n\n        if (tookDamage) { flashVignette(); Sound.shake(); }\n        floatDiffs(snap);\n        updateUI();\n    }\n\n    function startAttack() {\n        if (state.isAiming || state.gamePaused) return;\n\n        let cost = 1;\n        if (state.scenario === 'desert' && !state.exclusiveBought1) cost = 2;\n        if (state.scenario === 'blockade' && !state.exclusiveBought3) cost = 3;\n        if (state.scenario === 'blockade' && state.exclusiveBought3) cost = 2;\n        if (state.scenario === 'falklands' && !state.exclusiveBought1) cost = 2;\n\n        if (state.supplies < cost) { Sound.deny(); return; }\n        state.supplies -= cost; \n\n        if (state.scenario === 'attrition') { \n            resolveAttack(true, 0, cost); \n            tutorialAdvanceIf('attack');\n            return; \n        }\n\n        Sound.click();\n        state.isAiming = true;\n        el('radar-wrap').style.display = 'block'; \n        el('controls-wrap').style.display = 'none';\n        \n        cancelAnimationFrame(anim); // Prevence proti dublov\u00e1n\u00ed smy\u010dky\n        anim = requestAnimationFrame(radarLoop);\n        tutorialAdvanceIf('attack');\n    }\n    \n    function radarLoop() {\n        let speed = 360 - Math.min(180, state.day * 2.5);\n        if (state.scenario === 'modern_ew' && state.modern_counterTimer <= 0) speed = 35; \n        if (state.scenario === 'modern_ew' && state.exclusiveBought1) speed *= 1.3;\n        if (state.scenario === 'space') speed = state.exclusiveBought1 ? 120 : 60; \n        if (state.scenario === 'cyber_rebel') {\n            // Rychlost radaru kol\u00eds\u00e1\n            speed = 40 + Math.sin(Date.now() / 800) * 25;\n        }\n        if (state.scenario === 'desert' && !state.exclusiveBought3) {\n            // P\u00edse\u010dn\u00e1 bou\u0159e nepravideln\u011b rozkmit\u00e1v\u00e1 radar\n            speed *= (0.7 + Math.abs(Math.sin(Date.now() / 2200)) * 0.5);\n        }\n\n        state.currentPointerPos = 50 + Math.sin(Date.now() / speed) * 48;\n        el('pointer').style.left = `${state.currentPointerPos}%`;\n        anim = requestAnimationFrame(radarLoop);\n    }\n\n    el('radar').addEventListener('click', () => {\n        if (!state.isAiming) return;\n        cancelAnimationFrame(anim); \n        state.isAiming = false;\n        \n        let cost = 1;\n        if (state.scenario === 'desert' && !state.exclusiveBought1) cost = 2;\n        if (state.scenario === 'blockade' && !state.exclusiveBought3) cost = 3;\n        if (state.scenario === 'blockade' && state.exclusiveBought3) cost = 2;\n        if (state.scenario === 'falklands' && !state.exclusiveBought1) cost = 2;\n\n        resolveAttack(false, Math.abs(state.currentPointerPos - 50), cost);\n        tutorialAdvanceIf('radarClick');\n    });\n\n    function resolveAttack(isAuto, dist, costSpent) {\n        let threshold = getRadarWidth() / 2;\n        let dmgMult = getDmgMult();\n        let cpMult = getCpMult();\n        let _snap = { f: state.front, s: state.supplies, c: state.cp };\n        \n        let dmg = 0, cp = 0, msg = \"\", col = \"t-orange\", isHit = false, sndType = 'hit';\n\n        // V\u00fdpo\u010det \u0161ance na kritick\u00fd z\u00e1sah\n        let critChance = state.doctrine === 'intel' ? 0.40 : (state.doctrine === 'artillery' ? 0.05 : 0.15);\n        if (state.scenario === 'vietnam' && state.exclusiveBought2 && state.viet_revealed > 0) critChance += 0.20;\n        if (state.scenario === 'falklands') critChance += 0.10;\n        critChance += getSynergyBonus('crit');\n        \n        // P\u0159i\u010dten\u00ed glob\u00e1ln\u00edho v\u00fdzkumu kritiky\n        critChance += (state.upgrades.critical.level - 1) * 0.05;\n\n        if (isAuto || dist <= threshold) {\n            let isCrit = Math.random() < critChance;\n            dmg = Math.floor(30 * dmgMult); \n            cp = Math.floor(15 * cpMult); \n            isHit = true; \n            col = \"t-green\";\n            \n            if (!isAuto && dist < 2 && state.doctrine === 'intel') { \n                cp += Math.floor(20 * cpMult); \n                msg = `ABSOLUTN\u00cd ST\u0158ED (+${cp} VB)!`; \n                triggerShake(); \n                sndType = 'perfect';\n                spawnParticles('#fbbf24', 18);\n            }\n            else if (isCrit) { \n                // Crit po\u0161kozen\u00ed roste o +10% za \u00farove\u0148 v\u00fdzkumu\n                let critBonus = 1 + ((state.upgrades.critical.level - 1) * 0.10);\n                if (state.scenario === 'falklands' && state.exclusiveBought2) critBonus += 0.30;\n                dmg = Math.floor(55 * dmgMult * critBonus); \n                cp += Math.floor(10 * cpMult); \n                msg = `PERFEKTN\u00cd \u00daDER!`; \n                triggerShake(); \n                sndType = 'crit';\n                spawnParticles('#10b981', 16);\n                if (state.doctrine === 'blitz') { \n                    state.supplies += costSpent; \n                    msg += \" (Blitz: Zdarma!)\"; \n                }\n            } else { \n                msg = `P\u0159esn\u00fd z\u00e1sah!`; \n                sndType = 'hit';\n            }\n            \n            if (state.scenario === 'zombie' && state.exclusiveBought1 && state.zombie_mutation > 0) { \n                state.zombie_mutation--; \n                msg += \" (-1 Mutace)\"; \n            }\n        } else if (dist <= threshold + 15 + ((state.upgrades.intel_gain.level - 1) * 3)) { \n            dmg = Math.floor(10 * dmgMult); \n            cp = Math.floor(5 * cpMult); \n            isHit = true; \n            msg = `Standardn\u00ed postup.`; \n            sndType = 'graze';\n        } else { \n            // Selh\u00e1n\u00ed ofenz\u00edvy: Rozv\u011bdka m\u00e1 \u0161anci zachr\u00e1nit z\u00e1soby (10% za \u00farove\u0148)\n            let saveChance = (state.upgrades.intel_gain.level - 1) * 0.10;\n            if (Math.random() < saveChance) {\n                state.supplies += costSpent;\n                msg = `Ofenz\u00edva odvol\u00e1na. Rozv\u011bdka zachr\u00e1nila z\u00e1soby!`;\n                col = \"t-cyan\";\n                sndType = 'save';\n            } else {\n                dmg = 2; \n                cp = 1; \n                msg = `Ofenz\u00edva selhala.`; \n                col = \"t-red\"; \n                sndType = 'miss';\n                if (state.scenario === 'zombie') { \n                    state.zombie_mutation++; \n                    msg += \" ZOMBIE MUTUJ\u00cd (+1 Tlak)!\"; \n                    col = \"t-toxic\"; \n                    triggerShake(); \n                }\n            }\n        }\n        \n        let pct = (state.front / state.maxFront) * 100;\n        if (state.doctrine === 'fanatic' && pct < 35 && isHit) { \n            dmg = Math.floor(dmg * 1.5); \n            msg += \" (Fanatick\u00e1 zu\u0159ivost +50% Dmg)\"; \n        }\n        if (state.doctrine === 'partisan' && state.enemyStunned > 0 && isHit) { \n            dmg = Math.floor(dmg * 1.5); \n            msg += \" (Pr\u016fraz partyz\u00e1n\u016f x1.5)\"; \n        }\n        if (state.doctrine === 'fleet' && dist <= threshold && isHit) {\n            if (Math.random() < 0.30) {\n                state.supplies += costSpent;\n                msg += \" (Admir\u00e1l: Logistika vrac\u00ed z\u00e1soby!)\";\n            }\n        }\n        if (state.doctrine === 'chemical' && isHit && Math.random() < 0.15) {\n            state.enemyStunned = Math.max(state.enemyStunned, 1);\n            msg += \" (Toxic: Nep\u0159\u00edtel ochromen!)\";\n        }\n\n        if (state.scenario === 'default' && state.exclusiveBought2 && isHit) cp += Math.floor(2 * cpMult);\n\n        if (state.scenario === 'guerilla' && isHit) { \n            let steal = state.exclusiveBought1 ? 4 : 2; \n            state.supplies += steal; \n            msg += ` (Ukradeno +${steal} Z)`; \n        }\n        if (state.scenario === 'blockade' && isHit && state.exclusiveBought2) { \n            state.supplies += 2; \n            msg += ` (Pa\u0161ov\u00e1n\u00ed +2 Z)`; \n        }\n        if (state.scenario === 'cyber_rebel' && isHit) {\n            cp += Math.floor(20 * cpMult);\n            msg += \" (Rebelie bonus +20 VB)\";\n            if (state.exclusiveBought2 && Math.random() < 0.40) {\n                state.enemyStunned = Math.max(state.enemyStunned, 1);\n                msg += \" (De\u0161ifrov\u00e1no: Nep\u0159\u00edtel ochromen!)\";\n            }\n        }\n\n        if (state.scenario === 'ww1_west') { \n            state.ww1_trenchPrep += dmg; \n            msg += ` (Z\u00e1kop +${dmg})`; \n            dmg = 0; \n        } \n        else if (state.scenario === 'ww2_blitz') {\n            if (isHit) { \n                if (state.ww2_momentumEnemy > 0) state.ww2_momentumEnemy = 0; \n                else { state.ww2_momentumPlayer++; } \n            } \n            else { \n                if (state.exclusiveBought1) state.ww2_momentumPlayer = Math.max(0, state.ww2_momentumPlayer - 1); \n                else state.ww2_momentumPlayer = 0; \n                state.ww2_momentumEnemy++; \n            }\n        }\n\n        // Vy\u0159e\u0161en\u00ed po\u0161kozen\u00ed v\u016f\u010di mimozemsk\u00e9mu \u0161t\u00edtu\n        if (state.scenario === 'alien_inv' && isHit) {\n            if (state.exclusiveBought3) {\n                state.front += Math.floor(dmg * 1.3); // Ignorov\u00e1n\u00ed \u0161t\u00edtu + 30% bonus po\u0161kozen\u00ed\n            } else {\n                if (state.alienShield > 0) {\n                    let blocked = Math.min(state.alienShield, dmg);\n                    state.alienShield -= blocked;\n                    dmg -= blocked;\n                    msg += ` (\u0160t\u00edt absorboval: -${blocked} HP, zb\u00fdv\u00e1 mu ${state.alienShield} HP)`;\n                }\n                state.front += dmg;\n            }\n        } else {\n            state.front += dmg;\n        }\n\n        state.cp += cp;\n        if (!isAuto) { \n            el('radar-wrap').style.display = 'none'; \n            el('controls-wrap').style.display = 'block'; \n        }\n        Sound[sndType] ? Sound[sndType]() : Sound.hit();\n        floatDiffs(_snap);\n        endTurn(`OFENZ\u00cdVA: ${msg} ${dmg > 0 ? '(+'+dmg+' FR)' : ''} (+${cp} VB)`, col);\n    }\n\n    function doLogistics() {\n        let cost = state.doctrine === 'fortress' ? 5 : 12;\n        if (state.scenario === 'winter_war' && state.exclusiveBought2) cost = 0;\n        if (state.scenario === 'ww2_pacific') cost = 0;\n        if (state.scenario === 'nuke_winter' && state.exclusiveBought3) cost = Math.max(0, cost - 3);\n        if (state.doctrine === 'quartermaster' && state.supplies < 5) { \n            cost = 0; \n            logMessage(\"Z\u00c1SOBY: Nouzov\u00e1 logistika uchr\u00e1n\u011bna rezervami (Akce bez postihu Fronty).\", \"t-gold\"); \n        }\n\n        if (state.front <= cost) { \n            logMessage(\"ZAM\u00cdTNUTO: Linie je p\u0159\u00edli\u0161 k\u0159ehk\u00e1 na oslaben\u00ed!\", \"t-red\"); \n            Sound.deny();\n            return; \n        }\n        \n        let supMult = getSupplyMult();\n        let baseGain = 5;\n        if (state.doctrine === 'quartermaster') baseGain += 3;\n        if (state.doctrine === 'fortress') baseGain = Math.max(1, baseGain - 1);\n        if (state.scenario === 'ww2_pacific') baseGain = 2; \n        if (state.scenario === 'ww1_east') baseGain = Math.max(1, baseGain - 3); \n        if (state.scenario === 'guerilla') { cost = 10; baseGain = 1; } \n\n        let gain = Math.floor(baseGain * supMult);\n\n        if (state.scenario === 'ww2_blitz') { \n            state.ww2_momentumPlayer = 0; \n            state.ww2_momentumEnemy++; \n        }\n\n        let _snapLog = { f: state.front, s: state.supplies, c: state.cp };\n        state.supplies += gain; \n        state.front -= cost;\n        Sound.resupply();\n        floatDiffs(_snapLog);\n        endTurn(`Zabezpe\u010den\u00ed z\u00e1zem\u00ed (-${cost} FR). Dod\u00e1no +${gain} Z.`, \"t-orange\");\n        tutorialAdvanceIf('logistics');\n    }\n\n    function useArtillery() {\n        if (state.cp < state.costArt) return; \n        let _snapArt = { f: state.front, s: state.supplies, c: state.cp };\n        state.cp -= state.costArt; \n        state.enemyStunned = state.doctrine === 'artillery' ? 2 : 1; \n        \n        let dmg = Math.floor(25 * getDmgMult());\n        if (state.scenario === 'alien_inv' && state.exclusiveBought1) {\n            state.alienShield = 0;\n            spawnParticles('#06b6d4', 20);\n            applyInstantAction(`HQ: Iontov\u00e1 bar\u00e1\u017e kompletn\u011b p\u0159et\u00ed\u017eila nep\u0159\u00e1telsk\u00fd \u0161t\u00edt!`, \"t-cyan\", _snapArt, 'boom');\n            return;\n        }\n\n        if (state.scenario === 'ww1_west') { \n            state.ww1_trenchPrep += dmg; \n            applyInstantAction(`HQ: D\u011blost\u0159electvo pos\u00edlilo zte\u010d (+${dmg}). Nep\u0159\u00edtel ochromen na ${state.enemyStunned} d.!`, \"t-blue\", _snapArt, 'boom'); \n        }\n        else { \n            state.front += dmg; \n            triggerShake(); \n            spawnParticles('#3b82f6', 16);\n            applyInstantAction(`HQ: D\u011blost\u0159eleck\u00e1 bar\u00e1\u017e (+${dmg} FR). Nep\u0159\u00edtel ochromen na ${state.enemyStunned} d.!`, \"t-blue\", _snapArt, 'boom'); \n        }\n    }\n    \n    function useAirdrop() { \n        if (state.cp < state.costAir) return; \n        let _snapAir = { f: state.front, s: state.supplies, c: state.cp };\n        state.cp -= state.costAir; \n        let airGain = Math.floor(6 * getSupplyMult());\n        if (state.scenario === 'korea' && state.exclusiveBought1) airGain = Math.floor(airGain * 1.5);\n        state.supplies += airGain; \n        \n        if (state.scenario === 'ww2_blitz' && state.exclusiveBought2) { \n            state.front += 30; \n            triggerShake(); \n            applyInstantAction(`HQ: Shoz dorazil (+${airGain} Z) a doprovodn\u00e9 bombard\u00e9ry STUKAS vy\u010distily linii (+30 FR)!`, \"t-blue\", _snapAir, 'drop'); \n        }\n        else { \n            applyInstantAction(`HQ: Leteck\u00e9 z\u00e1soby shozeny (+${airGain} Z).`, \"t-blue\", _snapAir, 'drop'); \n        }\n    }\n\n    function useScenarioSkill() {\n        let skCost = state.doctrine === 'artillery' ? 0.75 : 1;\n        let dmgMult = getDmgMult();\n        let _snapSk = { f: state.front, s: state.supplies, c: state.cp };\n        \n        if (state.scenario === 'ww1_west') {\n            if (state.ww1_trenchPrep <= 0) return; \n            let burst = Math.floor(state.ww1_trenchPrep * (state.exclusiveBought1 ? 2.5 : 1.5) * dmgMult);\n            state.front += burst; \n            state.ww1_trenchPrep = 0; \n            triggerShake(); \n            spawnParticles('#a855f7', 18);\n            applyInstantAction(`SKILL: NA ZTE\u010c! Prora\u017een\u00ed nep\u0159\u00e1telsk\u00fdch lini\u00ed (+${burst} FR)!`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'ww1_east') {\n            let cost = state.exclusiveBought1 ? 5 : 15; \n            if (state.front <= cost) return;\n            state.front -= cost; \n            let sup = Math.floor(5 * getSupplyMult()); \n            state.supplies += sup; \n            applyInstantAction(`SKILL: Rekv\u00edrov\u00e1n\u00ed! (+${sup} Z), \u00fastup z pozic (-${cost} FR).`, \"t-purple\", _snapSk, 'resupply');\n        } else if (state.scenario === 'ww2_blitz') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            state.ww2_momentumPlayer += 2; \n            state.ww2_momentumEnemy = 0; \n            applyInstantAction(\"SKILL: Bleskov\u00fd pr\u016flom na\u0159\u00edzen! Z\u00edsk\u00e1v\u00e1\u0161 okam\u017eitou hybnost.\", \"t-purple\", _snapSk, 'buy');\n        } else if (state.scenario === 'ww2_pacific') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            state.supplies += Math.floor(15 * getSupplyMult()); \n            applyInstantAction(`SKILL: Vykl\u00e1dka z konvoje \u00fasp\u011b\u0161n\u011b dokon\u010dena (+${Math.floor(15 * getSupplyMult())} Z).`, \"t-purple\", _snapSk, 'drop');\n        } else if (state.scenario === 'winter_war') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            state.supplies += Math.floor(3 * getSupplyMult()); \n            state.enemyStunned = state.exclusiveBought3 ? 3 : 1; \n            applyInstantAction(`SKILL: Sissi p\u0159epad! (+${Math.floor(3 * getSupplyMult())} Z). Nep\u0159\u00edtel ochromen.`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'vietnam') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            state.viet_revealed = state.exclusiveBought1 ? 6 : 3; \n            let dmg = Math.floor(25 * dmgMult); \n            state.front += dmg; \n            if (state.exclusiveBought3) state.supplies += 3;\n            triggerShake(); \n            spawnParticles('#f59e0b', 16);\n            applyInstantAction(`SKILL: Napalmov\u00fd \u00fatok (+${dmg} FR). D\u017eungle odhalena.`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'modern_ew') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            state.modern_counterTimer = 3; \n            applyInstantAction(\"SKILL: Kybernetick\u00fd proti\u00fader! Filtry stabilizuj\u00ed radar.\", \"t-purple\", _snapSk, 'buy');\n        } else if (state.scenario === 'desert') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            let dmg = Math.floor(60 * dmgMult); \n            state.front += dmg; \n            state.enemyStunned = 1; \n            triggerShake(); \n            spawnParticles('#f59e0b', 16);\n            applyInstantAction(`SKILL: Kobercov\u00fd n\u00e1let! (+${dmg} FR). C\u00edl ochromen.`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'urban') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            let dmg = Math.floor(30 * dmgMult); \n            state.front += dmg; \n            triggerShake(); \n            applyInstantAction(`SKILL: Ost\u0159elova\u010di eliminovali velen\u00ed v sektoru (+${dmg} FR).`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'guerilla') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            let dmg = Math.floor(30 * dmgMult); \n            state.front += dmg; \n            state.enemyStunned = 1; \n            triggerShake(); \n            applyInstantAction(`SKILL: No\u010dn\u00ed p\u0159epaden\u00ed skladi\u0161t\u011b (+${dmg} FR, Ochromen\u00ed).`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'drone') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            let mult = state.exclusiveBought3 ? 1.3 : 1.0;\n            let dmg = Math.floor(40 * dmgMult * mult); \n            state.front += dmg; \n            triggerShake(); \n            applyInstantAction(`SKILL: P\u0159esn\u00fd \u00fader roj\u016f UAV (+${dmg} FR).`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'zombie') {\n            if (state.cp < state.costSkill || state.zombie_mutation === 0) return; \n            state.cp -= state.costSkill; \n            state.zombie_mutation = 0; \n            triggerShake(); \n            spawnParticles('#84cc16', 16);\n            applyInstantAction(\"SKILL: Chemick\u00e1 o\u010dista! \u00darove\u0148 n\u00e1kazy zresetov\u00e1na na 0.\", \"t-toxic\", _snapSk, 'unlock');\n        } else if (state.scenario === 'space') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            let dmg = Math.floor(80 * dmgMult); \n            state.front += dmg; \n            triggerShake(); \n            spawnParticles('#06b6d4', 22);\n            applyInstantAction(`SKILL: ORBIT\u00c1LN\u00cd LASER AKTIVOV\u00c1N (+${dmg} FR).`, \"t-cyan\", _snapSk, 'boom');\n        } else if (state.scenario === 'blockade') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            state.supplies += Math.floor(12 * getSupplyMult()); \n            let dmg = Math.floor(20 * dmgMult); \n            state.front += dmg; \n            applyInstantAction(`SKILL: Prolomen\u00ed koridoru silou (+${Math.floor(12 * getSupplyMult())} Z, +${dmg} FR).`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'attrition') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill; \n            let dmg = Math.floor(65 * dmgMult); \n            state.front += dmg; \n            triggerShake(); \n            spawnParticles('#ef4444', 18);\n            applyInstantAction(`SKILL: Lidsk\u00e1 vlna prora\u017een\u00ed (+${dmg} FR).`, \"t-red\", _snapSk, 'boom');\n        }\n        \n        // Nov\u00e9 dovednosti sc\u00e9n\u00e1\u0159\u016f\n        else if (state.scenario === 'cyber_rebel') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill;\n            let bDmg = Math.floor(40 * dmgMult); \n            state.front += bDmg;\n            let bSup = Math.floor(4 * getSupplyMult()); \n            state.supplies += bSup;\n            applyInstantAction(`SKILL: P\u0159et\u00ed\u017een\u00ed s\u00edt\u011b rebel\u016f! (+${bDmg} FR, +${bSup} Z)`, \"t-cyan\", _snapSk, 'boom');\n        } else if (state.scenario === 'nuke_winter') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill;\n            state.enemyStunned = 2;\n            applyInstantAction(\"SKILL: Um\u011bl\u00e1 sn\u011bhov\u00e1 bou\u0159e! Nep\u0159\u00edtel kompletn\u011b zamra\u017een na 2 dny.\", \"t-blue\", _snapSk, 'buy');\n        } else if (state.scenario === 'alien_inv') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill;\n            state.alienShield = 0;\n            spawnParticles('#06b6d4', 20);\n            applyInstantAction(\"SKILL: Masivn\u00ed EMP v\u00fdboj! Energetick\u00fd \u0161t\u00edt mimozem\u0161\u0165an\u016f zkratov\u00e1n.\", \"t-cyan\", _snapSk, 'boom');\n        }\n        \n        // Dovednosti nov\u00fdch sc\u00e9n\u00e1\u0159\u016f\n        else if (state.scenario === 'napoleon_siege') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill;\n            let dmg = Math.floor(45 * dmgMult); \n            state.front += dmg; \n            triggerShake(); \n            spawnParticles('#92400e', 16);\n            applyInstantAction(`SKILL: D\u011blost\u0159eleck\u00fd sbor zah\u00e1jil palbu (+${dmg} FR).`, \"t-orange\", _snapSk, 'boom');\n        } else if (state.scenario === 'korea') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill;\n            let dmg = Math.floor(55 * dmgMult); \n            state.front += dmg; \n            state.enemyStunned = 1;\n            triggerShake(); \n            spawnParticles('#16a34a', 18);\n            applyInstantAction(`SKILL: Kobercov\u00e9 bombardov\u00e1n\u00ed OSN (+${dmg} FR). Nep\u0159\u00edtel ochromen.`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'yom_kippur') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill;\n            let dmg = Math.floor(50 * dmgMult); \n            state.front += dmg; \n            triggerShake(); \n            spawnParticles('#16a34a', 16);\n            applyInstantAction(`SKILL: Obrn\u011bn\u00fd proti\u00fatok pror\u00e1\u017e\u00ed linie (+${dmg} FR).`, \"t-purple\", _snapSk, 'boom');\n        } else if (state.scenario === 'falklands') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill;\n            let dmg = Math.floor(45 * dmgMult); \n            state.front += dmg; \n            let sup = Math.floor(4 * getSupplyMult());\n            state.supplies += sup;\n            triggerShake(); \n            spawnParticles('#2563eb', 16);\n            applyInstantAction(`SKILL: N\u00e1mo\u0159n\u00ed bombardov\u00e1n\u00ed (+${dmg} FR, +${sup} Z).`, \"t-blue\", _snapSk, 'boom');\n        } else if (state.scenario === 'mars_colony') {\n            if (state.cp < state.costSkill) return; \n            state.cp -= state.costSkill;\n            let dmg = Math.floor(70 * dmgMult); \n            state.front += dmg; \n            triggerShake(); \n            spawnParticles('#dc2626', 20);\n            applyInstantAction(`SKILL: Orbit\u00e1ln\u00ed svr\u017een\u00ed kamene zas\u00e1hlo c\u00edl (+${dmg} FR).`, \"t-red\", _snapSk, 'boom');\n        }\n    }\n\n    function buyUpgrade(key) {\n        let u = state.upgrades[key];\n        if (state.cp >= u.cost) {\n            let _snapU = { f: state.front, s: state.supplies, c: state.cp };\n            state.cp -= u.cost; \n            u.level++; \n            \n            let multiplier = state.doctrine === 'tech' ? 1.4 : 1.6;\n            u.cost = Math.round(u.cost * multiplier); \n            \n            if (state.doctrine === 'tech') { \n                state.front += 10; \n                applyInstantAction(`V\u00ddZKUM: ${u.name.toUpperCase()} Lv.${u.level} (Tech bonus +10 FR)`, \"t-cyan\", _snapU, 'buy'); \n            }\n            else { \n                applyInstantAction(`V\u00ddZKUM: ${u.name.toUpperCase()} posunut na \u00farove\u0148 ${u.level}`, \"t-blue\", _snapU, 'buy'); \n            }\n        } else {\n            Sound.deny();\n        }\n    }\n\n    function buyExclusiveTech(id) {\n        let ex = id === 1 ? getExclusive1() : (id === 2 ? getExclusive2() : getExclusive3());\n        if (state.cp >= ex.cost && state[`exclusiveBought${id}`] === false) { \n            let _snapEx = { f: state.front, s: state.supplies, c: state.cp };\n            state.cp -= ex.cost; \n            state[`exclusiveBought${id}`] = true; \n\n            // BARIK\u00c1DY / OPEVN\u011aN\u00cd / V\u00ddSADEK: jednor\u00e1zov\u011b nav\u00fd\u0161\u00ed strop fronty pro tento sektor\n            if (state.scenario === 'urban' && id === 3) {\n                state.maxFront = Math.floor(state.maxFront * 1.30);\n            }\n            if (state.scenario === 'napoleon_siege' && id === 3) {\n                state.maxFront = Math.floor(state.maxFront * 1.25);\n            }\n            if (state.scenario === 'falklands' && id === 3) {\n                state.maxFront = Math.floor(state.maxFront * 1.20);\n            }\n\n            spawnParticles('#fbbf24', 22);\n            applyInstantAction(`\u2605\u2605 TECHNOLOGIE Z\u00cdSK\u00c1NA: ${ex.name} \u2605\u2605`, \"t-gold\", _snapEx, 'unlock'); \n        } else if (state.cp < ex.cost) {\n            Sound.deny();\n        }\n    }\n\n    // NEPR\u016eST\u0158ELN\u00dd FALLBACK KOP\u00cdROV\u00c1N\u00cd PRO V\u0160ECHNY PROHL\u00cd\u017dE\u010cE\n    function copyScore() {\n        let text = `\ud83c\udf96\ufe0f WARROOM: FRONTLINES\\n\ud83d\udccd Sc\u00e9n\u00e1\u0159: ${el('lbl-scenario').innerText}\\n\ud83e\udde0 Doktr\u00edna: ${el('lbl-doctrine').innerText}\\n\ud83d\udc80 P\u0159e\u017eito dn\u00ed: ${state.day}\\n\ud83d\udea9 Dobyt\u00e9 sektory: ${state.sector - 1}\\nDok\u00e1\u017ee\u0161 p\u0159ekonat m\u00e9 sk\u00f3re?`;\n        \n        if (navigator.clipboard && navigator.clipboard.writeText) {\n            navigator.clipboard.writeText(text).then(() => {\n                el('btn-copy').innerText = \"ZKOP\u00cdROV\u00c1NO DO SCHR\u00c1NKY!\";\n            }).catch(() => fallbackCopy(text));\n        } else {\n            fallbackCopy(text);\n        }\n    }\n\n    function fallbackCopy(text) {\n        const textArea = document.createElement(\"textarea\");\n        textArea.value = text;\n        textArea.style.position = \"fixed\"; \n        document.body.appendChild(textArea);\n        textArea.focus();\n        textArea.select();\n        try {\n            document.execCommand('copy');\n            el('btn-copy').innerText = \"ZKOP\u00cdROV\u00c1NO!\";\n        } catch (err) {\n            alert(\"Automatick\u00e9 zkop\u00edrov\u00e1n\u00ed selhalo. Zde je v\u00fdsledek pro ru\u010dn\u00ed kopii:\\n\\n\" + text);\n        }\n        document.body.removeChild(textArea);\n    }\n\n    function checkWinLoss() {\n        if (state.front >= state.maxFront && !state.gamePaused) {\n            state.gamePaused = true;\n            el('os-title').innerText = state.scenario === 'ww2_pacific' ? `OSTROV ${state.sector} DOBYT` : `SEKTOR ${state.sector} ZABR\u00c1N`;\n            \n            // Vyhodnocen\u00ed permanentn\u00edch unlock\u016f\n            checkSectorUnlockProgression();\n            \n            Sound.victory();\n            flashPanel(true);\n            el('overlay-sector').style.display = 'flex';\n            spawnParticles('#10b981', 26, 'overlay-sector');\n        } else if (state.front <= 0 && !state.gamePaused) {\n            if (state.doctrine === 'fanatic' && !state.fanaticUsed) { \n                state.front = 1; \n                state.fanaticUsed = true; \n                logMessage(\"V\u00cdRA: Voj\u00e1ci odm\u00edtli ustoupit! Posledn\u00ed linie dr\u017e\u00ed na 1 HP!\", \"t-purple\"); \n                Sound.crit();\n                flashVignette();\n                return; \n            }\n            state.gamePaused = true;\n            Sound.defeat();\n            let msg = state.scenario === 'ww2_pacific' ? \"ZATLA\u010cENI DO MO\u0158E\" : \"ARM\u00c1DA ZNI\u010cENA\";\n            if(state.scenario === 'zombie') msg = \"SE\u017dR\u00c1NI ZA\u017dIVA\"; \n            if(state.scenario === 'space') msg = \"ORBIT\u00c1LN\u00cd KOLAPS\";\n            if(state.scenario === 'alien_inv') msg = \"KAPITULACE LIDSTVA\";\n            \n            document.body.innerHTML = `<div id=\"vignette-flash\"></div>\n            <button id=\"sound-toggle\" class=\"${Sound.isMuted() ? 'muted' : ''}\" onclick=\"toggleSound()\" title=\"Zapnout/vypnout zvuk\">${Sound.isMuted() ? '\ud83d\udd07' : '\ud83d\udd0a'}</button>\n            <div class=\"wizard-screen active glass-panel\" style=\"border-color:var(--danger)\">\n                <h1 class=\"t-red\">${msg}</h1>\n                <p>Udr\u017eel jsi linie po dobu <b>${state.day} dn\u00ed</b> a vy\u010distil celkem ${state.sector - 1} sektor\u016f.</p>\n                <div style=\"display:flex; flex-direction:column; gap:10px; align-items:center; margin-top:20px;\">\n                    <button id=\"btn-copy\" class=\"btn-spec\" onclick=\"copyScore()\" style=\"padding:15px; width: 300px; font-size:1rem;\">ZKOP\u00cdROVAT VOJENSK\u00c9 HL\u00c1\u0160EN\u00cd</button>\n                    <button class=\"btn-main\" onclick=\"location.reload()\" style=\"padding:15px; width: 300px; font-size:1rem;\">NOV\u00c9 TA\u017dEN\u00cd</button>\n                </div>\n            </div>`;\n        }\n    }\n\n    function nextSector() {\n        Sound.resupply();\n        el('overlay-sector').style.display = 'none'; \n        state.sector++; \n        state.supplies += 5; \n        state.cp += 50;\n        \n        // Dynamick\u00e9 \u0161k\u00e1lov\u00e1n\u00ed maxim\u00e1ln\u00edho c\u00edle sektoru o +15%\n        let baseMax = getScenarioBaseMaxFront(state.scenario);\n        let currentMaxScaled = Math.floor(baseMax * (1 + (state.sector - 1) * 0.15));\n        state.maxFront = currentMaxScaled;\n        \n        let engBonus = 1 + ((state.upgrades.engineering.level - 1) * 0.05);\n        state.front = Math.floor(currentMaxScaled * 0.6 * engBonus);\n        \n        if (state.scenario === 'ww2_pacific') { \n            state.supplies += state.exclusiveBought1 ? 15 : 8; \n            state.maxFront = Math.floor(200 * (1 + (state.sector - 1) * 0.15));\n            state.front = Math.floor(state.maxFront * 0.6 * engBonus);\n            if (state.exclusiveBought3) state.front = Math.floor(state.front * 1.15);\n        } \n        \n        // Reset prom\u011bnn\u00fdch kola\n        state.ww1_trenchPrep = 0; \n        state.ww2_momentumEnemy = 0; \n        state.ww2_momentumPlayer = 0; \n        state.viet_revealed = 0;\n        state.gamePaused = false; \n        state.fanaticUsed = false;\n        \n        state.exclusiveBought1 = false;\n        state.exclusiveBought2 = false;\n        state.exclusiveBought3 = false;\n\n        if (state.scenario === 'alien_inv') {\n            state.alienShield = 150 + (state.sector - 1) * 50;\n        }\n        \n        logMessage(`--- VSTUP DO SEKTORU ${state.sector} (C\u00edl fronty nav\u00fd\u0161en o obt\u00ed\u017enost) ---`, \"t-green\");\n        updateUI();\n    }\n\n    window.onload = () => {\n        initWizards();\n    };\n</script>\n</body>\n</html>\n";
